var LESSONS = LESSONS || [];
LESSONS.push(
{
  "provenance": ["Số liệu trong sự cố, dòng thời gian và cách làm ngây thơ là giả định để dựng kịch bản, không phải số đo từ một hệ thống thật.","Các khẳng định về mã trạng thái HTTP, về preflight CORS và về cách một thư viện HTTP phía trình duyệt phân loại response được đối chiếu với tài liệu chính thức trong refs; phần còn lại là mô hình suy ra từ chúng."],
  "id": "L18",
  "stage": 4,
  "stageTitle": "Chặng 4 — Nối hai mảng",
  "stageIntro": "<p>Chặng này ghép hai mảng yếu của bạn vào một đường đi duy nhất: một lần bấm trên trình duyệt đi qua hợp đồng API, qua lớp xác thực, qua tệp trên S3, qua hàng đợi, rồi tới cơ sở dữ liệu và bản deploy. Không có cú pháp mới; mỗi bài thêm đúng một khớp nối và chỉ ra chỗ khớp đó vỡ khi tải cao, khi mạng chập chờn, hoặc khi hai lần deploy chồng lên nhau.</p>",
  "title": "Hợp đồng API giữa Vue và FastAPI",
  "goal": "Trong bài này bạn phải vẽ lại được đường đi của một response từ FastAPI tới Vue và chỉ đúng ba chỗ: nơi máy đọc kết quả, nơi người đọc chi tiết, và nơi cả hai được sinh ra; sau đó chọn đúng mã cho ba tình huống — dữ liệu sai hình dạng, SKU bị chặn, tạo mới thành công — và giải thích vì sao đổi một trường trong body mà không đổi mã lại làm vỡ client cũ.",
  "bridge": "Bạn đã biết chặn double submit bằng Idempotency-Key và biết một handler async chạy ở đâu; giờ hai thứ đó phải nằm trong một hợp đồng mà cả hai đầu đọc giống nhau, để kết quả nghiệp vụ không còn phải đoán từ một chuỗi thông báo trong body.",
  "buildsOn": ["L07","L17"],
  "incident": "<p><strong>Không có thứ này thì đau ở đâu?</strong> Giả sử 100 nhân viên nội bộ thử tính năng đặt hàng. Một buổi chiều, 37 người bấm Đặt hàng với SKU nằm trong danh sách chặn.</p><p>Server trả <code>200</code> kèm body <code>{\"ok\": false}</code>. Trình duyệt thấy <code>res.ok === true</code> nên chạy nhánh thành công và hiện toast xanh. Dashboard lỗi đếm số response có mã <code>&gt;= 400</code>, nên tỉ lệ lỗi đứng ở 0%.</p><p>Kết quả: 37 người thấy thông báo thành công, 0 đơn được tạo, và không có alert nào kêu. Sai ở chỗ hai đầu dùng hai hợp đồng khác nhau cho cùng một API: một bên đọc body, một bên đọc mã.</p><p>Sáng hôm sau, phía Vue gửi thêm một header tuỳ biến <code>X-Tenant-Id</code> cho mỗi request, nhưng backend chưa khai header đó trong <code>Access-Control-Allow-Headers</code>. Từ 9 giờ, mọi POST dừng trước khi chạm server: trình duyệt chặn ngay ở bước <code>preflight request</code>, nên log FastAPI trống hoàn toàn và nhìn vào thì tưởng không ai gọi.</p><p>Thứ còn thiếu là <code>API contract</code> (hợp đồng giao tiếp quy định khuôn dữ liệu và mã trạng thái giữa frontend và backend). Có nó, lệch bị chặn lúc build thay vì lúc người dùng bấm nút.</p>",
  "askFirst": ["Nếu cả hai đầu đều tin request đã thành công, dấu hiệu nào trong response đã bị bỏ qua?","Khi toast báo thành công mà bản ghi không tồn tại, tầng nào quyết định sai và nó dựa vào dữ liệu gì?","Muốn hai đầu không lệch nhau khi một trường mới xuất hiện, thứ gì phải được sinh ra từ cùng một nguồn?"],
  "predict": {"q":"Một route trả 409 kèm envelope {code, message, correlation_id}. Phía Vue có hai interceptor: A kiểm err.response.status === 409, B đọc err.response.data.error. Nếu backend đổi sang trả 200 kèm {error: \"sku bị chặn\"}, mỗi interceptor có chạy không, và cái nào còn đúng?","a":"<p>Với 409 và envelope hiện tại: A chạy vì status khớp; B không chạy vì envelope không có trường <code>error</code>, nên <code>data.error</code> là undefined. Với 200 kèm <code>{error}</code>: A không chạy vì status không khớp 409, và B cũng không chạy vì B chỉ được gắn vào nhánh lỗi — response 2xx không đi vào nhánh đó. Kết quả là cả hai im lặng, giao diện coi như thành công, đúng như sự cố trong bài. Kết luận: sau khi envelope đổi, chỉ A còn đúng, vì nó đọc kết quả từ status; B phụ thuộc tên trường nên vỡ mỗi lần envelope đổi tên.</p>"},
  "naive": "<p><strong>Cách tệ (làm theo phản xạ):</strong> coi body là nơi chứa kết quả, còn mã trạng thái là chi tiết trang trí.</p><ul><li><strong>Niềm tin:</strong> route nào cũng trả <code>200</code> rồi nhét <code>ok: false</code> vào body, vì client chỉ cần đọc một trường là biết kết quả.</li><li><strong>Vì sao nghe hợp lý:</strong> khi chỉ có một client do chính bạn viết, bạn luôn nhớ đọc trường đó, và mọi lần thử tay đều xanh.</li><li><strong>Chỗ chết:</strong> những tầng bạn không viết — thư viện HTTP, cache, gateway, log, alert — chỉ đọc mã. Chúng thấy <code>200</code> và cho qua, còn trường <code>ok</code> thì không tầng nào đọc.</li></ul>",
  "naiveCode": "# ❌ Mọi route trả 200; kết quả thật nằm trong body.\nfrom itertools import count\n\nfrom fastapi import FastAPI\nfrom pydantic import BaseModel\n\napp = FastAPI()\nBANNED_SKUS = {\"banned-sku\"}\n_ids = count(1)\n\n\nclass CreateOrder(BaseModel):\n    sku: str\n    qty: int\n\n\n@app.post(\"/orders\")\nasync def create_order(body: CreateOrder):\n    if body.sku in BANNED_SKUS:\n        # Không có mã lỗi nào: FastAPI trả 200 OK.\n        return {\"ok\": False, \"error\": \"sku đang bị chặn\"}\n    # Không khai response_model: dict trả nguyên vẹn, kể cả trường nội bộ.\n    return {\"ok\": True, \"order\": {\"id\": next(_ids), \"internal_note\": \"chờ kế toán duyệt\"}}",
  "naiveOut": "Gọi POST /orders với sku=banned-sku: server trả 200 kèm body báo lỗi. Phía Vue, lời gọi không ném exception nên state chuyển sang xong và toast xanh hiện ra. Access log của FastAPI cũng ghi 200, nên tỉ lệ lỗi trên dashboard không nhích. Ở nhánh thành công, response còn mang internal_note — trường nội bộ lẽ ra không được ra ngoài. Không có exception nào ở bất kỳ đâu; chỉ có một quyết định thiết kế sai được lặp lại ở mọi route.",
  "timeline": [["14:02:11","Bản pilot mở cho 100 người dùng nội bộ; POST /orders chạy ổn định với p99 giả định 180 ms."],["14:05:30","Danh sách SKU bị chặn được bật; 37 người dùng có mã nằm trong danh sách đó."],["14:05:31","Cả 37 request trả 200 kèm trường error trong body; không request nào trả 4xx."],["14:05:32","Phía Vue nhận 200 nên chạy nhánh thành công và hiện toast xanh cho cả 37 người."],["14:20:00","Hỗ trợ bắt đầu nhận ticket; access log của FastAPI toàn 200 nên không ai thấy lỗi."],["Hôm sau 09:01","Phía Vue gửi thêm header X-Tenant-Id; backend chưa khai trong allow-headers nên trình duyệt chặn ngay ở preflight; log server trống."]],
  "rootCause": "<p>Ba mắt xích nối tiếp nhau.</p><ul><li>Kết quả nghiệp vụ bị mã hoá vào body, nên <code>200</code> chỉ còn nghĩa là server đã trả lời.</li><li>Vì mã không mang kết quả, mỗi client phải tự học một quy ước riêng, và quy ước đó không nằm trong thứ gì máy kiểm được.</li><li>Vì không có gì máy kiểm được, thay đổi hình dạng body chỉ lộ ra qua lỗi runtime, hoặc qua preflight bị chặn trước khi request chạm server.</li></ul>",
  "concept": "Status code là kết quả dành cho máy, body là chi tiết dành cho người; một hợp đồng API chỉ đúng khi cả hai kênh được sinh ra từ cùng một schema, và mọi client đọc kết quả từ status chứ không đoán theo tên trường trong JSON.",
  "mechanism": "<p><strong>Ví von đời thường:</strong> hợp đồng API giống biên lai chuyển khoản — con số là kết quả, dòng ghi chú chỉ là lời giải thích, và máy đối soát chỉ đọc con số. Giới hạn: biên lai giấy không sửa được sau khi in, còn body JSON thì sửa được ở mọi bản deploy, nên hợp đồng phải sinh từ một nguồn chứ không từ kỷ luật người viết.</p><pre><code>Vue ──POST /orders──→ Pydantic ──sai hình dạng──→ 422 + details\n                          │\n                          └─đúng──→ Handler ──SKU bị chặn──→ 409 + envelope\n                                        │\n                                        └─tạo mới──→ 201 + Location\n                                                        │\n                              response_model lọc ───────┘\n                                        │\n                                        ▼\n                            Vue đọc status, không đọc tên trường</code></pre><ol><li><strong>Bước 1 — Một response có hai người đọc:</strong> máy đọc mã trạng thái, người đọc câu thông báo; hai kênh khác nhau nên chúng có thể nói hai điều trái nhau.</li><li><strong>Bước 2 — Máy chỉ đọc được mã:</strong> thư viện HTTP, cache, gateway, access log và alert đều phân loại theo mã, không tầng nào đọc trường <code>ok</code>.</li><li><strong>Bước 3 — Nên kết quả phải đi bằng mã:</strong> <code>201</code> tạo mới kèm <code>Location</code>, <code>409</code> xung đột nghiệp vụ, <code>422</code> sai hình dạng, <code>403</code> thiếu quyền; body chỉ còn chở chi tiết và <code>correlation_id</code>.</li><li><strong>Bước 4 — Cả hai kênh sinh từ một nguồn:</strong> model Pydantic khai hình dạng, FastAPI sinh mã, sinh <code>response_model</code> (khuôn lọc và kiểm tra dữ liệu trả về của FastAPI) và sinh <code>openapi.json</code> để client lấy kiểu.</li></ol>",
  "visuals": [{"id": "flow-api-contract", "question": "Một response đi qua những trạm nào, và trạm nào đọc kết quả thành công hay thất bại?", "focus": "Status code"}],
  "failureModes": "<p>Hợp đồng chặt cũng tạo ra bốn kiểu hỏng mới.</p><ul><li><strong>Thêm trường bắt buộc.</strong> Niềm tin sai: thêm một trường là thay đổi nhỏ. Nghe hợp lý vì server tự tin nó đúng. Điều đúng: trường mới phải có giá trị mặc định, hoặc đi hai giai đoạn — server chấp nhận cả thiếu lẫn có, rồi mới siết. Phản chứng: ngay sau deploy, log đầy <code>422</code> với <code>missing</code> ở đúng trường mới, từ những client chưa cập nhật.</li><li><strong>Trả thẳng dict nội bộ.</strong> Niềm tin sai: trả gì cũng được, client chỉ đọc trường nó cần. Nghe hợp lý vì test tay vẫn qua. Điều đúng: phải có <code>response_model</code> làm màng lọc đầu ra. Phản chứng: response chứa <code>internal_note</code>, và lần sau đổi tên trường đó lại thành thay đổi hợp đồng ngoài ý muốn.</li><li><strong>Envelope không nhất quán.</strong> Niềm tin sai: route nào có nhánh lỗi là đủ. Nghe hợp lý vì mỗi route đều xử lý lỗi của nó. Điều đúng: hình dạng lỗi phải giống nhau ở mọi route. Phản chứng: interceptor phải rẽ nhánh theo URL, và nhánh nào cũng có thể sai mà không ai thấy.</li><li><strong>Không kiểm hợp đồng trong CI.</strong> Niềm tin sai: đổi tên trường là việc riêng của backend. Nghe hợp lý vì code vẫn chạy. Điều đúng: client phải được sinh và typecheck từ schema. Phản chứng: màn hình hiện <code>undefined</code> hoặc <code>NaN</code> ngay sau deploy, còn log server không có một lỗi nào.</li></ul>",
  "tradeoff": "<p><strong>Được gì:</strong> kết quả thành bại nằm ở đúng một kênh máy đọc, nên cache, gateway, log và alert xử lý đúng mà không cần hiểu nghiệp vụ; lệch schema bị chặn ở CI thay vì ở người dùng; trường nội bộ không lọt ra vì màng lọc là khai báo.</p><p><strong>Mất gì:</strong> mỗi trường mới phải trả lời ba câu — bắt buộc hay tuỳ chọn, có lộ ra ngoài không, client cũ chịu được không. Pipeline phía client đỏ mỗi lần schema đổi, nên hai đội phải phối hợp trước khi deploy.</p><p><strong>Rủi ro:</strong> thêm một trường bắt buộc là làm vỡ client cũ ngay sau deploy, và triệu chứng là một loạt <code>422</code> chứ không phải một lỗi rõ ràng.</p><p><strong>Vì sao vẫn đáng:</strong> từ hai client trở lên, một lần deploy sai hợp đồng tốn hơn một buổi chiều viết schema.</p>",
  "alternatives": "<p><strong>Khi nào KHÔNG nên dùng:</strong> khi chưa có client thứ hai, hoặc khi chỉ có một webhook nội bộ một chiều không ai đọc lại body.</p><ul><li><strong>Prototype một người làm cả hai đầu:</strong> trả dict tự do nhanh hơn, và chưa có ai để lệch hợp đồng.</li><li><strong>Webhook nội bộ một chiều:</strong> không có client thứ hai thì schema chỉ là giấy tờ không ai đọc.</li><li><strong>GraphQL:</strong> chọn khi client cần tự chọn trường; cái giá là lỗi vẫn nằm trong response <code>200</code> kèm mảng <code>errors</code>, đúng thứ bài này khuyên tránh.</li><li><strong>gRPC:</strong> chọn cho service nội bộ cần sinh client từ file <code>.proto</code>; cái giá là trình duyệt phải đi qua proxy.</li></ul><p>Ngay khi có client thứ hai, chuyển sang REST cộng OpenAPI thay vì viết tài liệu tay.</p>",
  "observe": "<p><strong>Bốn tín hiệu cho biết hợp đồng đã lệch.</strong></p><ul><li><strong>Phân bố status theo route.</strong> Một route chỉ toàn <code>2xx</code> trong khi nghiệp vụ chắc chắn có từ chối là dấu hiệu kết quả đang nằm trong body. Đọc từ access log hoặc metric của gateway, tách theo từng route.</li><li><strong>Lỗi preflight.</strong> Sau mỗi lần thêm header, gọi một <code>OPTIONS</code> thật. Nếu bỏ qua, lỗi CORS chỉ hiện ở trình duyệt người dùng và không để lại dòng log nào phía server.</li><li><strong>Correlation id.</strong> Mỗi lỗi trả về client phải tra được trong log. Nếu người dùng báo lỗi mà bạn không tìm ra dòng log tương ứng, envelope đang thiếu mảnh nối cuối cùng.</li><li><strong>Diff schema giữa hai bản deploy.</strong> So <code>openapi.json</code> của bản mới với bản trước; một trường bắt buộc mới xuất hiện mà không có ghi chú là thay đổi phá vỡ tương thích, và nó phải bị chặn trước khi phát hành.</li></ul>",
  "attacks": [{"q":"Vì sao phải tách 422 và 409 thay vì trả 400 cho mọi lỗi phía client?","a":"<p><strong>Trả lời mẫu (30–60 giây):</strong> Mỗi mã là một chỉ thị cho interceptor, và ba mã này dẫn tới ba hành vi giao diện khác nhau. <code>422</code> nghĩa là sửa được tại chỗ, nên giao diện chiếu mảng <code>details</code> vào đúng ô nhập. <code>409</code> nghĩa là hình dạng đúng nhưng trạng thái đã đổi, nên phải tải lại trạng thái mới chứ sửa ô nhập vô ích. <code>400</code> chỉ dành cho gói tin hỏng ở mức giao thức. Gộp cả ba là mất thông tin mà không được gì.</p><p><strong>Lỗi hay mắc khi trả lời:</strong> nói \"400 là lỗi của client nên gộp cũng được\" — cách nói đúng là chỉ gộp khi client chỉ hiện một câu chung; hễ client rẽ nhánh theo mã thì mỗi mã phải mang một nghĩa riêng.</p>"},{"q":"Một SKU vừa bị chặn vừa vượt tồn kho — bạn trả mã nào, envelope ghi gì, và giao diện làm gì?","a":"<p><strong>Trả lời mẫu (30–60 giây):</strong> Chọn một mã theo lý do chặn chính, và ghi các lý do còn lại vào <code>details</code>; không trả hai mã cho một response. SKU nằm trong danh sách chặn thì <code>409</code> kèm <code>code: \"sku_blocked\"</code>. SKU hợp lệ nhưng thiếu tồn kho thì vẫn <code>409</code> với <code>code: \"out_of_stock\"</code> và <code>details</code> ghi số còn lại. <code>422</code> chỉ dành cho <code>qty</code> sai kiểu hoặc nhỏ hơn 1, tức lỗi hình dạng. Giao diện đọc <code>code</code> để rẽ nhánh, không đọc câu tiếng Việt.</p><p><strong>Lỗi hay mắc khi trả lời:</strong> nói \"trả 409 kèm câu thông báo là đủ\" — cách nói đúng là <code>code</code> phải là hằng chuỗi máy so được, còn <code>message</code> chỉ để người đọc.</p>"},{"q":"Nếu client thứ hai là app mobile đã phát hành và không thể cập nhật, bạn đổi schema theo trình tự nào?","a":"<p><strong>Trả lời mẫu (30–60 giây):</strong> Mở rộng trước, thu hẹp sau. Bước một, thêm trường mới vào <code>response_model</code> và vẫn trả trường cũ; mọi trường mới ở đầu vào phải có giá trị mặc định để request cũ vẫn qua được. Bước hai, client mới đọc trường mới, client cũ đọc trường cũ mà không biết gì đã đổi. Bước ba, chỉ xoá trường cũ khi metric chứng minh không còn request nào dùng nó trong một chu kỳ đủ dài. Với app mobile, cửa sổ đó tính bằng nhiều tháng.</p><p><strong>Lỗi hay mắc khi trả lời:</strong> nói \"đổi tên trường rồi thông báo cho đội mobile\" — cách nói đúng là người dùng không cập nhật app, nên chỉ có schema tương thích ngược mới cứu được.</p>"},{"q":"OpenAPI có bảo đảm hai đầu không lệch không, và nó không kiểm được điều gì?","a":"<p><strong>Trả lời mẫu (30–60 giây):</strong> Không. OpenAPI mô tả hình dạng, nên nó chỉ bắt được lệch hình dạng, và chỉ khi client thật sự được sinh từ nó. Nó không kiểm quyền: một endpoint khai đúng schema vẫn có thể trả dữ liệu của tenant khác nếu handler không lọc theo danh tính. Nó không kiểm ngữ nghĩa: <code>200</code> với <code>items</code> rỗng và <code>200</code> với <code>items</code> bị cắt trang đều hợp lệ theo schema. Nó cũng không nói gì về thứ tự theo thời gian.</p><p><strong>Lỗi hay mắc khi trả lời:</strong> nói \"có OpenAPI là hết lệch\" — cách nói đúng là nếu client viết tay thay vì sinh từ <code>openapi.json</code> thì giá trị bắt lỗi gần như bằng không.</p>"}],
  "anchor": "Status code là kết quả cho máy, body là chi tiết cho người, và cả hai phải sinh ra từ cùng một schema.",
  "say30": "Hợp đồng API là định nghĩa máy kiểm được về request, response và mã lỗi. Trong FastAPI nó nằm trong model Pydantic, và framework sinh OpenAPI từ chính model đó. Kết quả nghiệp vụ phải đi bằng status code, vì thư viện HTTP, cache và alert đều đọc mã; trả 200 kèm error trong body làm mọi tầng mù. Tôi trả 422 khi dữ liệu sai hình dạng, 409 khi xung đột nghiệp vụ, và gom mọi lỗi vào một envelope có correlation id.",
  "say90": "[Nêu vấn đề (30s)]: Hai đội viết hai đầu của một API bằng hai hợp đồng khác nhau. Backend trả 200 kèm trường error trong body, nên toast báo thành công trong khi đơn đã bị chặn, và dashboard lỗi không nhích vì mọi dòng log đều 200. Sáng hôm sau phía Vue gửi thêm header X-Tenant-Id mà backend chưa khai trong allow-headers, nên trình duyệt chặn ngay ở preflight và log server trống.\n\n[Cơ chế (45s)]: Tôi tách hai kênh. Status code là kết quả cho máy: 201 cho tạo mới kèm Location, 422 khi Pydantic chặn dữ liệu sai hình dạng, 409 khi SKU bị chặn, 403 khi thiếu quyền. Body là chi tiết cho người, gom vào một envelope có code, message và correlation_id từ một exception handler chung. Chiều ra đi qua response_model nên trường nội bộ không lọt. Cả hai kênh sinh từ cùng model Pydantic, nên openapi.json không lạc hậu và CI sinh client TypeScript để typecheck phía Vue.\n\n[Ranh giới (15s)]: Hợp đồng mô tả hình dạng chứ không phải phân quyền; quyền vẫn kiểm từng request ở backend. Và schema chặt vẫn phá client cũ nếu thêm trường bắt buộc, nên phải có giá trị mặc định.",
  "body": "<p><strong>Ví dụ chuyển giao.</strong> Một endpoint <code>GET /orders</code> trả mảng đơn, và một script đối soát đọc mảng đó mỗi đêm.</p><p>Khi danh sách vượt 5.000 đơn, backend đổi sang phân trang: body thành <code>{items, next_cursor}</code>, vẫn trả <code>200</code>.</p><p>Với mã trạng thái, không có gì đổi. Script vẫn nhận <code>200</code> và vẫn coi là thành công, nhưng <code>items</code> giờ chỉ còn 100 phần tử, nên đêm đó đối soát thiếu 4.900 đơn mà không có lỗi nào.</p><p>Cách đúng là thêm tham số <code>limit</code> với giá trị mặc định, giữ hình dạng cũ trong một giai đoạn, rồi ghi thay đổi vào schema để client sinh lại kiểu.</p><p>Ngược lại, nếu backend đổi <code>200</code> thành <code>206</code> cho phản hồi một phần thì script cũ vỡ ngay và ồn ào — đúng như mong muốn, vì nó đang hiểu sai dữ liệu.</p><p>Bài học: mã đổi thì lỗi lộ ra ngay và rẻ; body đổi âm thầm thì lỗi nằm im trong dữ liệu và chỉ hiện khi ai đó cộng số.</p>",
  "code": "# FastAPI: hợp đồng là type annotation + Pydantic model.\nfrom uuid import uuid4\n\nfrom fastapi import Depends, FastAPI, HTTPException, Request, Response, status\nfrom fastapi.encoders import jsonable_encoder\nfrom fastapi.exceptions import RequestValidationError\nfrom fastapi.responses import JSONResponse\nfrom pydantic import BaseModel, Field\n\napp = FastAPI()\nBANNED_SKUS = {\"banned-sku\"}\n\n\nasync def new_id() -> str:\n    return uuid4().hex\n\n\nclass CreateOrder(BaseModel):\n    sku: str = Field(min_length=1, max_length=64)\n    qty: int = Field(ge=1, le=999)\n\n\nclass OrderOut(BaseModel):\n    id: str\n    tenant_id: str\n    sku: str\n    qty: int\n\n\nclass Tenant(BaseModel):\n    tenant_id: str\n\n\nasync def get_tenant(request: Request) -> Tenant:\n    # Header do API Gateway chèn sau khi verify JWT, và gateway đã strip header cùng tên do client gửi lên.\n    # Tenant không bao giờ lấy từ body.\n    return Tenant(tenant_id=request.headers[\"x-tenant-id\"])\n\n\ndef envelope(request: Request, code: str, message: str, details=None) -> dict:\n    return {\"error\": {\"code\": code, \"message\": message,\n                      \"details\": details or [],\n                      \"correlation_id\": getattr(request.state, \"cid\", None)}}\n\n\n# Envelope do chính FastAPI sinh ra từ handler, không phải client tự lo.\n@app.exception_handler(RequestValidationError)\nasync def on_validation(request: Request, exc: RequestValidationError) -> JSONResponse:\n    return JSONResponse(\n        status_code=422,\n        content=envelope(request, \"VALIDATION_FAILED\", \"dữ liệu gửi sai hợp đồng\",\n                         jsonable_encoder(exc.errors())),\n    )\n\n\n@app.exception_handler(HTTPException)\nasync def on_business(request: Request, exc: HTTPException) -> JSONResponse:\n    return JSONResponse(\n        status_code=exc.status_code,\n        content=envelope(request, \"BUSINESS_RULE_FAILED\", exc.detail),\n    )\n\n\n@app.post(\n    \"/orders\",\n    response_model=OrderOut,\n    status_code=status.HTTP_201_CREATED,\n    responses={422: {\"description\": \"Validation failed\"}},\n)\nasync def create_order(\n    body: CreateOrder, response: Response, tenant: Tenant = Depends(get_tenant)\n):\n    if body.sku in BANNED_SKUS:\n        raise HTTPException(status_code=409, detail=\"sku đang bị chặn\")\n    order = OrderOut(id=await new_id(), tenant_id=tenant.tenant_id, sku=body.sku, qty=body.qty)\n    response.headers[\"Location\"] = f\"/orders/{order.id}\"   # 201 phải kèm Location\n    return order\n\n# Vue: một client HTTP dùng chung, interceptor dịch lỗi ở một chỗ.\n# api.post(\"/orders\", payload, { headers: { \"Idempotency-Key\": key } })\n# 422 -> chiếu vào từng ô; 401 -> refresh token rồi thử lại một lần;\n# 5xx -> hiện thông báo chung, log correlation id để báo cáo lỗi.",
  "codeNote": "<p><strong>Cách tệ so với cách tốt, nhìn từ khối code trên.</strong></p><ul><li><strong>Cách tệ:</strong> <code>return {\"ok\": False}</code> — request vẫn đi tiếp bình thường và mã vẫn là <code>200</code>, nên không tầng nào biết đã từ chối.</li><li><strong>Cách tốt:</strong> <code>raise HTTPException(status_code=409, ...)</code> — request dừng ngay tại chỗ ném, và exception handler biến nó thành envelope có cùng hình dạng.</li><li><code>response_model=OrderOut</code> là chỗ quyết định trường nào được ra ngoài; bỏ nó, dict trả về đi nguyên vẹn và trường nội bộ thành hợp đồng công khai.</li><li><code>status_code</code> cùng <code>response.headers[\"Location\"]</code> biến một lần ghi thành một tài nguyên có địa chỉ, nên client không phải đoán id từ body.</li><li>Đăng ký <code>@app.exception_handler(RequestValidationError)</code> để <code>422</code> mặc định của FastAPI không có hình dạng khác hẳn envelope của bạn.</li></ul>",
  "sayIt": ["Tôi mô hình hoá resource trước rồi mới đặt endpoint: danh sách đơn, một đơn theo id, và tạo mới trả 201 kèm Location chứ không phải 200.","Kết quả thành bại đi bằng mã: 422 cho dữ liệu sai hình dạng, 409 cho xung đột nghiệp vụ, 403 cho thiếu quyền; body chỉ chở chi tiết và correlation id.","Một schema sinh ra cả ba thứ: kiểm đầu vào, lọc đầu ra, và tài liệu OpenAPI; client được sinh từ đó nên lệch tên trường đỏ ở CI.","Đổi hợp đồng là đổi hình dạng body chứ không chỉ đổi mã: thêm trường phải có giá trị mặc định, xoá trường phải đi qua giai đoạn chấp nhận cả hai.","Thứ tôi kiểm trên production là phân bố mã theo route và diff openapi.json giữa hai bản deploy, vì cả hai đều là thứ máy đọc được."],
  "qids": ["E01","E02","E11","B14"],
  "refs": ["fastapi-tutorial","mdn-http-overview","mdn-cors"]
},
{
  "provenance": ["Số liệu trong sự cố, dòng thời gian và cách làm ngây thơ là giả định để dựng kịch bản, không phải số đo từ một hệ thống thật.","Các khẳng định về cookie HttpOnly, SameSite, CSRF và về cách một token hết hạn được cấp lại được đối chiếu với tài liệu chính thức trong refs; phần còn lại là mô hình suy ra từ chúng."],
  "id": "L19",
  "stage": 4,
  "stageTitle": "Chặng 4 — Nối hai mảng",
  "title": "Auth xuyên hai phía: token, nơi lưu, interceptor, và ai quyết định quyền",
  "goal": "Trong bài này bạn phải tính được số lời gọi refresh khi bốn mươi request cùng nhận 401, vẽ lại được đường đi của một lần refresh và một lần replay, chỉ ra chỗ nào phải chặn để không lặp vô hạn, và giải thích vì sao một token hợp lệ vẫn chưa phải là một request được phép.",
  "bridge": "Hợp đồng ở bài trước đã chốt rằng 401 là một kết quả máy đọc được, nên interceptor có thể xử lý nó ở một chỗ. Bài này đặt danh tính vào đúng chỗ đó: access token sống ngắn đi kèm mỗi request, refresh token sống dài chỉ để đổi token mới, và cả hai phải không nằm ở nơi mã lạ đọc được.",
  "buildsOn": ["L16","L18"],
  "incident": "<p><strong>Không có thứ này thì đau ở đâu?</strong> Giả sử 9h00 thứ Hai, khoảng 1.000 người mở ứng dụng trong vài phút đầu giờ. <code>access token</code> (thẻ truy cập ngắn hạn gửi kèm mỗi request) sống 15 phút, nên tới 9h15 gần một nghìn request cùng nhận <code>401</code>.</p><p>Mỗi request tự gọi <code>/auth/refresh</code>. Endpoint đó xoay vòng token: cấp cặp mới là <code>refresh token</code> (thẻ làm mới dài hạn) cũ chết ngay.</p><p>Kết quả: 1.024 lời gọi trong một giây, 1 thành công, 1.023 thất bại. Pool 20 connection bị chiếm hết và p99 của endpoint refresh lên 6,4 giây.</p><p>Không có lỗi <code>5xx</code> nào, nên alert im lặng. Thiếu <code>single-flight</code> (cơ chế gộp nhiều yêu cầu xin mới token cùng lúc thành đúng 1 lần gọi mạng) là toàn bộ nguyên nhân.</p>",
  "askFirst": ["Vì sao cùng một sự kiện token hết hạn lại sinh ra hơn một nghìn lời gọi refresh?","Khi lời gọi refresh thứ hai mang một refresh token vừa bị xoay vòng, điều gì khiến nó chắc chắn thất bại?","Nếu kéo hạn của access token lên một ngày, sự cố biến mất hay chỉ dời sang một thời điểm khác với quy mô lớn hơn?"],
  "predict": {"q":"Bốn mươi request cùng nhận 401 một lúc, interceptor dùng một Promise refresh chung. Trong bốn mươi request đó có đúng một request gọi tới /auth/refresh. Refresh chạy bao nhiêu lần, request tới /auth/refresh được xử lý thế nào, và nếu refresh thành công thì bao nhiêu request được gửi lại?","a":"<p>Refresh chạy đúng một lần: request đầu tạo Promise và lưu lại, 39 request còn lại chờ chính Promise đó thay vì tự gọi. Request tới <code>/auth/refresh</code> không được đưa vào nhóm chờ và không được gửi lại — nếu gửi lại, một refresh token đã bị xoay vòng sẽ sinh ra vòng lặp vô hạn, nên nó phải nhận lỗi và kết thúc. Vì vậy khi refresh thành công có 39 request được gửi lại với token mới, còn request thứ bốn mươi thì không. Nếu refresh thất bại, cả 39 request nhận cùng một lỗi, khóa được nhả trong <code>finally</code>, và ứng dụng đăng xuất đúng một lần thay vì thử lại.</p>"},
  "naive": "<p><strong>Cách tệ (làm theo phản xạ):</strong> coi refresh là việc của từng request, và coi chỗ lưu token là chi tiết không quan trọng.</p><ul><li><strong>Niềm tin:</strong> thấy <code>401</code> thì gọi refresh ngay trong interceptor của request đó, vì mỗi request tự lo là cách viết ít dòng nhất.</li><li><strong>Vì sao nghe hợp lý:</strong> với một người bấm từng nút, chỉ có một request bay tại một thời điểm, nên refresh chạy đúng một lần và mọi thứ xanh.</li><li><strong>Chỗ chết:</strong> khi nhiều request bay cùng lúc, mỗi request là một sự kiện độc lập nên <code>n</code> request sinh <code>n</code> lời gọi; và vì <code>token rotation</code> (xoay vòng thẻ), lời đầu làm chết đúng cái token mà những lời còn lại đang cầm.</li></ul>",
  "naiveCode": "// ❌ Cách làm sai phổ biến: lưu token trong localStorage cho tiện, và refresh ngay trong interceptor.\nfunction saveSession(res) {\n  localStorage.setItem(\"access_token\", res.data.access_token)\n  localStorage.setItem(\"refresh_token\", res.data.refresh_token)\n}\n\nhttp.interceptors.response.use(undefined, async (err) => {\n  if (err.response?.status !== 401) throw err\n  // Mỗi request 401 tự gọi refresh của riêng nó.\n  const r = await http.post(\"/auth/refresh\", {\n    refresh_token: localStorage.getItem(\"refresh_token\"),\n  })\n  localStorage.setItem(\"access_token\", r.data.access_token)\n  err.config.headers.Authorization = \"Bearer \" + r.data.access_token\n  return http.request(err.config)\n})",
  "naiveOut": "Ở một người dùng, mọi thứ xanh: token được lưu, header được gắn, và khi 401 xảy ra thì refresh chạy đúng một lần. Ở 1.000 người dùng cùng vào đầu giờ, log của API ghi 1.024 lời gọi /auth/refresh trong một giây và 1.023 lời gọi trả 401, vì xoay vòng làm mọi lời gọi refresh sau lời đầu tiên đều mang token đã chết. Pool 20 connection bị chiếm hết, p99 của endpoint refresh là 6,4 giây, và tab của người dùng quay vô hạn. Song song đó, một lỗi XSS ở bất kỳ thư viện bên thứ ba nào đọc được cả hai token từ localStorage và giả danh người dùng cho tới khi token hết hạn.",
  "timeline": [["08:58:40","Khoảng 1.000 người dùng đăng nhập trong vài phút; mỗi phiên có access token sống 15 phút."],["09:13:55","Những access token đầu tiên hết hạn; p50 của /auth/refresh là 58 ms (giả định)."],["09:14:01","Gần một nghìn request đồng thời nhận 401 và mỗi request tự gọi /auth/refresh."],["09:14:02","Lời gọi refresh đầu tiên xoay vòng token thành công; 1.023 lời gọi còn lại mang refresh token đã chết và nhận 401."],["09:14:03","Mỗi 401 lại kích hoạt một vòng thử lại, nên số lời gọi refresh tăng theo cấp số nhân."],["09:14:06","Pool 20 connection tới PostgreSQL bị chiếm hết; p99 của /auth/refresh là 6,4 giây."]],
  "rootCause": "<p>Ba mắt xích nối tiếp nhau.</p><ul><li>Refresh là việc dùng chung nhưng bị gọi ở cấp từng request, nên số lời gọi tỉ lệ với số request đang bay.</li><li>Vì endpoint xoay vòng token, lời đầu làm chết đúng cái refresh token mà <code>n-1</code> lời còn lại đang cầm — race condition phía client, không phải lỗi server.</li><li>Vì mỗi <code>401</code> lại kích hoạt một vòng thử lại, bão refresh tự nuôi mình: nó chiếm hết connection pool và làm mọi thứ trông như server chậm.</li></ul>",
  "concept": "Access token sống ngắn để mỗi request tự chứng minh danh tính, refresh token sống dài chỉ để đổi token mới; vì refresh là việc dùng chung, mọi request 401 phải chờ đúng một Promise, và quyền vẫn do backend quyết định ở từng request.",
  "mechanism": "<p><strong>Ví von đời thường:</strong> refresh token giống vé gửi xe có đánh số — mỗi lần lấy xe, vé cũ bị thu và đổi vé mới, nên 40 người cùng cầm bản photo của một vé thì chỉ người đầu lấy được xe. Giới hạn: bãi xe chỉ có một quầy, còn server refresh chịu được nhiều lời gọi đồng thời; cái chết ở đây là vé bị thu, không phải quầy quá tải.</p><pre><code>40 request mang access token hết hạn\n        │\n        ▼\n   cả 40 nhận 401\n        │\n   refreshPromise đã có?\n     ┌──┴───┐\n    chưa    rồi\n     │        │\n     ▼        ▼\n tạo 1 lời   chờ chính\n gọi refresh  Promise đó\n     │        │\n     └───┬────┘\n         ▼\n  cấp cặp mới, token cũ chết\n         │\n         ▼\n  gắn token mới, gửi lại đúng 1 lần</code></pre><ol><li><strong>Bước 1 — Một token thành hai:</strong> access token sống ngắn và đi kèm mọi request nên dễ lộ nhất; refresh token sống dài và chỉ dùng để đổi token mới, nên hai thứ có hai mức rủi ro khác nhau.</li><li><strong>Bước 2 — Chỗ lưu quyết định thiệt hại:</strong> access token giữ trong RAM, refresh token nằm trong cookie <code>HttpOnly</code> (loại cookie JavaScript không đọc được), nên một lỗ XSS không rút được phiên dài hạn.</li><li><strong>Bước 3 — 401 là chuyện của cả phiên:</strong> gộp bằng một biến <code>refreshPromise</code> dùng chung, nhả khóa trong <code>finally</code>, và một cờ đánh dấu đã replay để không xoay thêm vòng.</li><li><strong>Bước 4 — Quyền vẫn do backend quyết định:</strong> token hợp lệ chỉ chứng minh danh tính; mỗi request, FastAPI vẫn phải lọc truy vấn theo danh tính lấy từ token.</li></ol>",
  "visuals": [{"id": "flow-auth-refresh", "question": "Bốn mươi request cùng nhận 401 thì refresh chạy mấy lần, và cơ chế nào giữ con số đó ở mức một?", "focus": "Một refresh Promise"}],
  "failureModes": "<p>Bốn kiểu hỏng của chính cách sửa này.</p><ul><li><strong>Promise đã chết vẫn giữ khóa.</strong> Niềm tin sai: gán <code>refreshPromise = null</code> sau <code>await</code> là đủ. Nghe hợp lý vì đường thành công chạy đúng. Điều đúng: phải nhả trong <code>finally</code>, nếu không một lần reject là khóa vĩnh viễn. Phản chứng: từ lúc refresh lỗi, mọi request 401 sau đó treo tới khi người dùng F5, và log chỉ có 401 chứ không có lỗi nào khác.</li><li><strong>Vòng lặp trên chính endpoint refresh.</strong> Niềm tin sai: mọi 401 đều đáng được refresh. Nghe hợp lý vì 401 nghĩa là token hết hạn. Điều đúng: 401 từ <code>/auth/refresh</code> nghĩa là phiên đã chết, phải đăng xuất chứ không thử lại. Phản chứng: số lời gọi <code>/auth/refresh</code> trong log tăng theo cấp số nhân trong vài giây.</li><li><strong>Single-flight chỉ sống trong một tab.</strong> Niềm tin sai: một Promise là đủ cho cả ứng dụng. Nghe hợp lý vì trong một tab nó thật sự đúng. Điều đúng: phạm vi là một tab; hai tab phải đồng bộ qua <code>BroadcastChannel</code> hoặc storage event. Phản chứng: mở hai tab, tab xoay token sau làm tab kia nhận 401 dây chuyền dù người dùng không làm gì.</li><li><strong>Token hợp lệ bị coi là có quyền.</strong> Niềm tin sai: JWT đã ký và có claim role là đủ để cho qua. Nghe hợp lý vì chữ ký đúng thật. Điều đúng: quyền phải kiểm trên từng bản ghi theo danh tính lấy từ token. Phản chứng: đổi id trên URL trả về dữ liệu của tenant khác, và access log ghi 200 chứ không phải 403.</li></ul>",
  "tradeoff": "<p><strong>Được gì:</strong> một lỗi XSS không rút được phiên dài hạn ra khỏi tab; single-flight biến 1.000 lời gọi refresh thành đúng một; và vì endpoint refresh chỉ nhận cookie ở đúng một đường dẫn, bề mặt tấn công hẹp hơn hẳn.</p><p><strong>Mất gì:</strong> tải lại trang làm mất access token, nên mỗi lần khởi động phải chạy một lượt refresh im lặng — trang đầu chậm thêm một round trip và phải xử lý trạng thái \"đang khôi phục phiên\".</p><p><strong>Rủi ro:</strong> nhánh cookie kéo theo CSRF token, cấu hình <code>SameSite</code> và <code>Path</code>; ba thứ dễ cấu hình sai và khó tái hiện trên máy dev. Quên nhả khóa trong <code>finally</code> là mọi request sau đó treo tới khi người dùng F5.</p><p><strong>Vì sao vẫn đáng:</strong> cái mất là một round trip mỗi lần mở tab, còn cái được là phiên dài hạn không nằm trong tầm với của một lỗ XSS.</p>",
  "alternatives": "<p><strong>Khi nào KHÔNG nên dùng:</strong> khi ứng dụng không có dữ liệu nhạy cảm, hoặc khi client không phải trình duyệt.</p><ul><li><strong>Cookie HttpOnly cho cả hai token, server tự refresh:</strong> chọn khi app cùng domain với API; cái giá là mọi request đều mang cookie nên phải chống CSRF ở mọi endpoint ghi.</li><li><strong>Session opaque trong cơ sở dữ liệu:</strong> chọn khi cần thu hồi phiên ngay; cái giá là mỗi request tra một lần kho phiên.</li><li><strong>CLI hoặc script nội bộ dùng token tĩnh:</strong> single-flight chỉ thêm một biến trạng thái mà không cứu được gì, vì ở đó không có hàng trăm request đồng thời.</li><li><strong>Ủy thác cho identity provider bên ngoài:</strong> chọn khi xác thực không phải việc của đội bạn; cái giá là thêm một hệ thống phải cấu hình.</li></ul>",
  "observe": "<p><strong>Bốn tín hiệu, và tín hiệu thứ hai là tín hiệu bạn cần nhất.</strong></p><ul><li><strong>Tỉ lệ 401 theo route.</strong> Tăng đồng thời trên nhiều route là token hết hạn hàng loạt, không phải người dùng gõ sai mật khẩu.</li><li><strong>Số lời gọi <code>/auth/refresh</code> trên mỗi lần hết hạn.</strong> Con số đúng xấp xỉ 1. Vượt 1 rõ rệt nghĩa là single-flight không hoạt động; tăng theo cấp số nhân nghĩa là có vòng lặp.</li><li><strong>p99 của endpoint refresh.</strong> Endpoint này chạm cơ sở dữ liệu nên là chỗ đầu tiên cạn connection pool khi có bão refresh.</li><li><strong>Báo cáo CSP ở chế độ report-only.</strong> Đây là tín hiệu sớm nhất cho biết có XSS đang cố chạy trong tab người dùng, trước cả khi token bị dùng sai.</li></ul>",
  "attacks": [{"q":"Vì sao phải là một Promise dùng chung thay vì một hàng đợi request chờ refresh xong?","a":"<p><strong>Trả lời mẫu (30–60 giây):</strong> Cả hai đều gộp được, nhưng Promise dùng chung ít trạng thái hơn và tự nhả khi xong. Một hàng đợi cần ai đó nhớ khi nào mở cửa: refresh thành công thì xả, thất bại thì xả kèm lỗi, và quên một nhánh là request nằm chờ vĩnh viễn. Promise đã mang sẵn cả hai nhánh: <code>resolve</code> xả bình thường, <code>reject</code> lan lỗi cho mọi request đang chờ, và biến trỏ tới nó chỉ cần gán <code>null</code> trong <code>finally</code>.</p><p><strong>Lỗi hay mắc khi trả lời:</strong> nói \"hàng đợi tốt hơn vì kiểm soát được thứ tự\" — cách nói đúng là hàng đợi chỉ hơn khi cần giới hạn số request replay cùng lúc, và lúc đó bài toán là rate limit chứ không phải refresh.</p>"},{"q":"Bốn mươi request 401, trong đó mười hai request là POST ghi dữ liệu. Trước khi replay, cần điều kiện gì?","a":"<p><strong>Trả lời mẫu (30–60 giây):</strong> Cần hai điều kiện. Thứ nhất, request ghi phải mang <code>Idempotency-Key</code> để server nhận ra lần gửi lại là cùng một ý định, vì request có thể đã tới server và bị từ chối sau khi ghi. Thứ hai, chỉ replay đúng một lần và chỉ khi <code>401</code> đến từ request nghiệp vụ, không phải từ chính endpoint refresh. Không có hai điều kiện đó, replay biến một lần hết hạn token thành hai đơn hàng.</p><p><strong>Lỗi hay mắc khi trả lời:</strong> nói \"cứ replay là an toàn vì request đã bị 401\" — cách nói đúng là 401 có thể xảy ra sau khi server đã xử lý xong và chỉ hỏng ở bước trả lời.</p>"},{"q":"Nếu chuyển refresh token từ localStorage sang cookie HttpOnly, rủi ro mới là gì và bù bằng cách nào?","a":"<p><strong>Trả lời mẫu (30–60 giây):</strong> Rủi ro mới là CSRF: trình duyệt tự gửi cookie kèm request phát sinh từ site khác, nên kẻ tấn công không cần đọc token vẫn mượn được phiên. Bù bằng ba thứ: <code>SameSite=Strict</code> để chặn gửi cookie từ site khác, <code>Secure</code> để chỉ đi qua HTTPS, và <code>Path=/auth/refresh</code> để cookie chỉ tới đúng một đường dẫn. Với endpoint ghi, thêm CSRF token hoặc kiểm header <code>Origin</code>. Đổi lại, JavaScript không đọc được refresh token nữa.</p><p><strong>Lỗi hay mắc khi trả lời:</strong> nói \"có HttpOnly là hết rủi ro\" — cách nói đúng là HttpOnly chặn đọc, không chặn dùng; cookie vẫn được gửi kèm request do JavaScript khởi tạo.</p>"},{"q":"Single-flight không giải quyết được những gì?","a":"<p><strong>Trả lời mẫu (30–60 giây):</strong> Nó không giải quyết ba việc. Một, nó không làm phiên an toàn hơn: token vẫn nằm đâu đó và vẫn bị dùng nếu có XSS. Hai, nó không chặn được vòng lặp nếu <code>401</code> từ chính endpoint refresh cũng được đưa vào nhánh chờ — đó là việc của cờ chặn replay và của việc tách client gốc. Ba, nó không quyết định quyền: token hợp lệ vẫn có thể nhận <code>403</code>. Single-flight chỉ trả lời đúng một câu: refresh chạy mấy lần.</p><p><strong>Lỗi hay mắc khi trả lời:</strong> nói \"single-flight là đủ cho toàn bộ phần auth\" — cách nói đúng là nó chỉ là một cơ chế gộp, đứng cạnh ba cơ chế khác chứ không thay chúng.</p>"}],
  "anchor": "Refresh là việc dùng chung: mọi request 401 chờ đúng một Promise, và backend vẫn quyết định quyền ở từng request.",
  "say30": "Access token sống ngắn và đi kèm mọi request, còn refresh token sống lâu và chỉ dùng để đổi access token mới, nên khi access token bị lộ thì thiệt hại chỉ kéo dài tới lúc nó hết hạn. Khi token hết hạn đồng loạt, nếu mỗi request 401 tự refresh thì hàng nghìn lời gọi phá nhau vì refresh token xoay vòng. Tôi gộp bằng single-flight: một Promise dùng chung, nhả khóa trong finally, cờ đã thử để không lặp vô hạn.",
  "say90": "[Nêu vấn đề (30s)]: Access token sống ngắn đi kèm mọi request, refresh token sống lâu chỉ để đổi token mới, nên khi access token bị lộ thì thiệt hại chỉ kéo dài tới lúc nó hết hạn. Nỗi đau là token hết hạn đồng loạt: một nghìn request nhận 401 cùng lúc, mỗi request tự gọi refresh, và vì refresh token xoay vòng nên chỉ lời đầu sống.\n\n[Cơ chế (45s)]: Interceptor giữ một biến refreshPromise dùng chung. Request 401 đầu tiên tạo Promise và lưu lại, 39 request còn lại chờ chính nó; request tới endpoint refresh bị loại khỏi nhánh chờ để không lặp vô hạn; khóa được nhả trong finally và mỗi request chỉ replay một lần nhờ cờ đã thử. Về nơi lưu: access token trong RAM, refresh token trong cookie HttpOnly SameSite Strict ở đúng một đường dẫn, nên XSS không đọc được. Backend vẫn kiểm chữ ký, hạn, loại token và quyền trên từng bản ghi.\n\n[Ranh giới (15s)]: Single-flight chỉ sống trong một tab, không thu hồi được phiên đã phát hành, và không thay thế kiểm quyền ở backend. Cookie còn kéo theo rủi ro CSRF phải bù bằng SameSite và kiểm Origin.",
  "body": "<p><strong>Ví dụ chuyển giao.</strong> Một dashboard mở ra và bắn 18 lời gọi song song. Người dùng quay lại sau 16 phút, bấm làm mới, và cả 18 lời gọi cùng nhận <code>401</code>.</p><p>Không có single-flight, lần xoay vòng đầu tiên giết đúng cái token mà 17 lời còn lại đang cầm, nên cả trang đứng hình. Có single-flight, chỉ một lời gọi refresh tồn tại và 17 lời còn lại chờ nó; trang chậm thêm đúng một round trip rồi tất cả đi tiếp.</p><p>Cùng cơ chế đó xuất hiện ở chỗ không có trình duyệt. Một script Python gọi API bằng thư viện HTTP cũng gặp <code>401</code> và cũng cần một khóa dùng chung, chỉ khác là khóa nằm trong một biến module thay vì trong một interceptor.</p><p>Điều không đổi giữa hai chỗ: <code>401</code> là chuyện của cả phiên, nên phải có đúng một chỗ xử lý nó. Nếu mỗi chỗ gọi tự xử lý, số lời gọi refresh lại tỉ lệ với số chỗ gọi.</p>",
  "code": "// ✅ Cách làm chuẩn: một Promise refresh dùng chung cho cả đợt request 401.\nlet accessToken = null;      // chỉ nằm trong RAM, không vào localStorage\nlet refreshPromise = null;   // khoá single-flight\n\n// refreshFn do tầng gọi truyền vào (client HTTP của bạn). Hàm này không tự\n// mở kết nối nào, và refreshFn là client gốc chứ không phải hàm api() bên\n// dưới, nên request refresh không bao giờ quay lại đây thành vòng lặp.\nfunction getAccessToken(refreshFn) {\n  refreshPromise = refreshPromise ?? refreshFn();   // gộp: đợt sau dùng lại\n  return refreshPromise;\n}\n\n// Nhận thẳng đối tượng phản hồi { status, data } từ client, không tự gọi mạng.\nasync function handle401(res, { refreshFn, retry, retried = false }) {\n  if (res.status !== 401 || retried) return res;   // 401 lần hai: trả về\n  try {\n    accessToken = await getAccessToken(refreshFn);\n  } finally {\n    refreshPromise = null;      // nhả khoá kể cả khi refresh reject\n  }\n  return retry({ Authorization: `Bearer ${accessToken}`, retried: true });\n}\n",
  "codeNote": "<p><strong>Cách tệ so với cách tốt, nhìn từ khối code trên.</strong></p><ul><li><strong>Cách tệ:</strong> mỗi nhánh <code>401</code> tự gọi <code>http.post(\"/auth/refresh\")</code>, nên 40 request sinh 40 lời gọi và 39 lời sau cầm token đã chết.</li><li><strong>Cách tốt:</strong> <code>refreshPromise = refreshPromise ?? refreshFn()</code> — chỉ request nào thấy biến rỗng mới tạo lời gọi, số còn lại chờ chính Promise đó.</li><li><code>finally { refreshPromise = null }</code> là dòng dễ bỏ nhất và cũng dễ gây treo nhất: gán sau <code>await</code> trên nhánh thành công thì một lần reject là khóa vĩnh viễn.</li><li><code>refreshFn</code> được truyền vào chứ không tự gọi, nên <code>401</code> từ chính endpoint refresh không quay lại hàm này thành vòng lặp.</li><li><code>retried</code> chặn replay lần hai, nên một refresh token đã bị xoay vòng không sinh ra chuỗi thử lại.</li></ul>",
  "sayIt": ["Access token sống ngắn và đi kèm mỗi request, còn refresh token sống lâu chỉ để đổi lấy access token mới, nên khi access token bị lộ thì thiệt hại chỉ kéo dài tới lúc nó hết hạn.","Vue chỉ giữ token và gắn header, còn FastAPI mới là bên kiểm chữ ký, hạn, loại token và quyền trên từng tài nguyên, kể cả tenant và chủ sở hữu.","Tôi không để token trong localStorage vì XSS đọc được; tôi chọn access token trong memory và refresh token trong cookie HttpOnly, đổi lại lúc khởi động phải chạy một lượt refresh im lặng.","Khi gặp 401 thì phải refresh đúng một lần cho cả đợt request và chặn vòng lặp bằng cờ đã thử, nếu không ứng dụng sẽ treo với hàng trăm request cùng chờ.","Xoá token ở client không huỷ được phiên ở server, nên tôi xoay vòng refresh token và ghi jti để token cũ không dùng lại được."],
  "qids": ["E05","C10","B08","B14"],
  "refs": ["owasp-api-security","mdn-cookies","mdn-http-headers"]
},
{
  "provenance": ["Số liệu trong sự cố, dòng thời gian và cách làm ngây thơ là giả định để dựng kịch bản, không phải số đo từ một hệ thống thật.","Các khẳng định về cách S3 kiểm chữ ký, về hạn của presigned URL, về head_object và về hành vi của Versioning được đối chiếu với tài liệu chính thức trong refs; phần còn lại là mô hình suy ra từ chúng."],
  "id": "L20",
  "stage": 4,
  "stageTitle": "Chặng 4 — Nối hai mảng",
  "title": "Upload lên S3: ký quyền ghi, rồi xác nhận thứ thật sự nằm trong bucket",
  "goal": "Trong bài này bạn phải chỉ ra được, với một object đang nằm trong bucket, những gì phải đọc từ head_object để quyết định bản ghi upload được chuyển sang READY, và giải thích vì sao một presigned URL còn hạn không chứng minh được tệp nằm đó đúng như đã khai.",
  "bridge": "Bài trước chốt rằng client chỉ giữ token và gắn header, còn server mới quyết định quyền. Bài này dùng đúng header đó để xin một quyền hẹp hơn nhiều: quyền ghi một object, trong mười phút, trên một key do server đặt. Byte không đi qua API nữa, nên câu hỏi mới là ai xác nhận thứ đã nằm trong bucket.",
  "buildsOn": ["L05","L18","L19"],
  "incident": "<p><strong>Không có thứ này thì đau ở đâu?</strong> Giả sử một buổi sáng có 10.000 người tải tệp lên, mỗi tệp 5 MB. Server cấp <code>presigned URL</code> (đường dẫn có chữ ký số và hạn dùng để trình duyệt tải tệp thẳng lên S3) sống 600 giây.</p><p>Một người dùng mạng 3G nhận URL lúc 10:04:12. Đường lên 50 kbit/s nên tệp 5 MB cần khoảng 800 giây; người đó bấm gửi lúc 10:15 và nhận <code>403</code>, vì hạn tính từ lúc ký chứ không từ lúc byte bắt đầu đi.</p><p>Trong bucket còn 1.240 object không có hàng metadata nào trỏ tới, mỗi object 5 MB — khoảng 6 GB trả tiền mỗi tháng mà không ai giải thích được. Và một object 900 MB nằm ở key của một ảnh đại diện 5 MB, mang <code>Content-Type: text/html</code>.</p><p>Ba triệu chứng, một nguyên nhân: API cấp quyền rồi đứng ngoài, nên mọi thứ nó biết về tệp đều là lời khai của client.</p>",
  "askFirst": ["Vì sao URL còn hạn mười phút lại hết hạn đúng lúc người dùng mạng chậm cần nó nhất?","Nếu client đã PUT xong mà lời gọi xác nhận thất bại, thứ gì trong hệ thống biết tệp đó đang tồn tại?","API đã kiểm kích thước và loại tệp rồi, vì sao vẫn có một object 900 MB nằm trong bucket?"],
  "predict": {"q":"Hai lời gọi PUT cùng một presigned URL, cùng một key, cả hai trước hạn: lần đầu 5 MB, lần hai 900 MB. Nếu bucket không bật Versioning, head_object ở bước xác nhận đọc được gì, và bản ghi upload nên kết thúc ở trạng thái nào?","a":"<p><code>head_object</code> trả về bản mới nhất của key, tức là 900 MB, nên phép so kích thước bắt được và bản ghi phải kết thúc ở trạng thái lỗi. Nhưng cách sửa mới là phần đáng nói: xoá object theo key sẽ xoá luôn bản 5 MB hợp lệ, và nếu bản ghi đã READY từ trước thì mọi URL đọc phát hành theo key sẽ trả về bản độc. Nếu bucket có Versioning, <code>head_object</code> trả kèm <code>VersionId</code> của bản mới nhất, nên phải ghim đúng version đó ở bước xác nhận và ở mọi lần phục vụ; bản cũ vẫn nằm trong bucket và vẫn tốn dung lượng cho tới khi có lifecycle dọn. Nhánh thứ ba: nếu lần PUT thứ hai diễn ra sau khi bản ghi đã READY, thì không có bước xác nhận nào chạy lại để bắt nó — đó là lý do phải ký hạn ngắn và ghim version chứ không chỉ kiểm một lần.</p>"},
  "naive": "<p><strong>Cách tệ (làm theo phản xạ):</strong> coi presigned URL là bằng chứng về nội dung, và coi hạn URL là chi tiết cấu hình.</p><ul><li><strong>Niềm tin:</strong> S3 chỉ nhận đúng thứ client đã khai, nên cấp URL xong là coi như tệp đã đúng; bước xác nhận chỉ cần đánh dấu bản ghi sang <code>READY</code>.</li><li><strong>Vì sao nghe hợp lý:</strong> với một người dùng gửi một ảnh đúng như khai, mọi thứ khớp, và bước xác nhận chỉ tốn thêm một lời gọi vô nghĩa.</li><li><strong>Chỗ chết:</strong> URL dùng lại được trong suốt thời hạn và chữ ký không mang kích thước, nên một URL đã cấp có thể nhận byte khác hẳn lời khai; và nếu bản ghi không được ghi trước khi ký, một lần xác nhận thất bại là object không còn ai chủ.</li></ul>",
  "naiveCode": "# ❌ Cách làm sai phổ biến: API nhận key từ client, ký URL dài hạn, không ràng buộc header.\n@app.post(\"/uploads/presign\")\nasync def presign(body: PresignIn, user=Depends(current_user)):\n    key = body.file_name            # client tự chọn key: có thể ghi đè tệp của người khác\n    url = s3.generate_presigned_url(\n        ClientMethod=\"put_object\",\n        Params={\"Bucket\": BUCKET, \"Key\": key},\n        ExpiresIn=86400,            # một ngày, cho tiện\n    )\n    return {\"url\": url, \"key\": key}\n\n# Client PUT thẳng lên S3 bằng chính URL này. Không có bước xác nhận,\n# không có bản ghi metadata, không có gì ràng buộc nội dung.",
  "naiveOut": "Với 10 người dùng thử nội bộ, mọi thứ xanh: URL được cấp, tệp lên, và không ai để ý là không có hàng metadata nào. Ở 10.000 người dùng, ba dấu vết xuất hiện. Kiểm tra <code>head_object</code> một object nằm ở key của một ảnh đại diện thấy <code>ContentLength</code> khoảng 900 MB và <code>ContentType</code> là <code>text/html</code>, vì chữ ký không mang theo ràng buộc kích thước lẫn loại nội dung nào để S3 thực thi. Trong danh sách object có 1.240 object không có hàng metadata tương ứng, mỗi object 5 MB, tổng khoảng 6 GB dữ liệu không ai quản lý. Và vì URL sống một ngày, một tệp đã được quét xong vẫn có thể bị ghi đè bằng nội dung khác trong cùng ngày hôm đó.",
  "timeline": [["10:02:00","10.000 người dùng bắt đầu tải tệp, mỗi tệp trung bình 5 MB (giả định)."],["10:04:12","Một người dùng mạng 3G nhận presigned URL sống 10 phút."],["10:15:12","PUT đầu tiên của người đó nhận 403 vì URL đã hết hạn; bấm gửi lại cũng 403."],["10:31:40","Một client PUT xong 5 MB rồi mất mạng trước khi gọi xác nhận."],["11:00:00","Kiểm tra ngẫu nhiên thấy object 900 MB ở key của một ảnh đại diện, mang Content-Type text/html."],["Cuối ngày","Đếm ra 1.240 object không có hàng metadata nào trỏ tới, khoảng 6 GB (giả định)."]],
  "rootCause": "<p>Ba mắt xích, và mắt thứ ba là mắt khó thấy nhất.</p><ul><li>Hạn của URL tính từ lúc ký, không từ lúc byte bắt đầu đi, nên người dùng mạng chậm chắc chắn gặp <code>403</code> và không có cách nào cứu URL đã hết hạn.</li><li>Nếu bản ghi upload không được ghi trước khi ký, một lần xác nhận thất bại để lại object không có hàng nào trỏ tới.</li><li>Chữ ký không mang kích thước, và nếu đọc lẫn phục vụ đều theo key thay vì theo version thì byte được kiểm và byte được phục vụ là hai đối tượng khác nhau.</li></ul>",
  "concept": "Presigned URL là quyền ghi có hạn trên một key do server đặt, không phải bằng chứng về nội dung; vì vậy server ghi bản ghi chờ trước khi ký, và chỉ chuyển sang READY sau khi head_object đối chiếu kích thước, key và metadata của đúng version đã quét.",
  "mechanism": "<p><strong>Ví von đời thường:</strong> presigned URL giống phiếu gửi hàng có ghi giờ hết hiệu lực và địa chỉ kho — phiếu cho phép bạn tự mang hàng tới kho, nhưng không ghi hàng nặng bao nhiêu, và ai nhặt được phiếu cũng dùng được. Giới hạn: phiếu giấy chỉ dùng một lần, còn presigned URL dùng lại được nhiều lần cho tới hạn, nên nó không chống được ghi đè.</p><pre><code>Vue ──POST /uploads/presign──→ API ──ghi PENDING──→ PostgreSQL\n                                │\n                                └──ký URL 10 phút──→ Vue\n                                                      │\n                                       PUT byte thẳng (API không thấy)\n                                                      ▼\n                                                     S3\n                                                      │\nVue ──POST /uploads/{id}/confirm──→ API ──head_object─┘\n                                     │\n                        khớp ────────┴──────── lệch\n                         │                       │\n                    SCANNING → READY      xoá đúng VersionId</code></pre><ol><li><strong>Bước 1 — Byte không đi qua API:</strong> trình duyệt nói chuyện trực tiếp với S3, nên 50 GB không phải đi qua cổng hai lần, nhưng API cũng thôi làm nhân chứng.</li><li><strong>Bước 2 — Chữ ký chỉ ràng buộc thứ đã ký:</strong> <code>Content-Type</code> ký được nên S3 tự từ chối request sai header; <code>Content-Length</code> thì không, vì trình duyệt tự đặt header đó và JavaScript không được sửa.</li><li><strong>Bước 3 — Nên phải có bước xác nhận:</strong> <code>head_object</code> trả metadata mà không trả body — kích thước, content type, <code>VersionId</code>, và <code>ETag</code> (mã băm kiểm tra tính toàn vẹn của đối tượng) — rồi so với bản ghi đã khai.</li><li><strong>Bước 4 — Ghi bản ghi trước khi ký:</strong> ký trước rồi mới ghi thì một lần ghi hỏng để lại URL không ai giữ ID; ghi trước thì chỉ còn một hàng <code>PENDING</code> mà worker dọn xử lý.</li></ol>",
  "visuals": [{"id": "flow-upload-confirm", "question": "Làm sao biết object thật trong S3 khớp với bản ghi upload, khi API không hề thấy byte nào?", "focus": "head_object"}],
  "failureModes": "<p>Bốn kiểu hỏng của chính cách sửa này.</p><ul><li><strong>Hạn ngắn đẩy lỗi sang người mạng chậm.</strong> Niềm tin sai: rút hạn URL xuống là an toàn hơn. Nghe hợp lý vì cửa sổ bị lạm dụng hẹp lại thật. Điều đúng: nó không chặn được ghi đè trong hạn, mà chỉ dời lỗi sang nhóm người dùng mạng chậm nhất, và 403 không nói cho client biết phải xin URL mới. Phản chứng: tỉ lệ 403 tăng đúng ở nhóm mạng chậm, còn số object bị ghi đè không đổi.</li><li><strong>Dọn object mồ côi xoá nhầm.</strong> Niềm tin sai: bản ghi quá hạn thì object xoá được. Nghe hợp lý vì bản ghi quá hạn trông như rác. Điều đúng: phải chờ dài hơn thời gian xác nhận tối đa và phải kiểm object có thật trước khi xoá. Phản chứng: người dùng báo tệp vừa tải xong đã biến mất, và log confirm ghi 404 ở bước head_object.</li><li><strong>Versioning phình dung lượng.</strong> Niềm tin sai: bật Versioning là xong phần an toàn. Nghe hợp lý vì version làm object bất biến thật. Điều đúng: mỗi lần ghi sinh một version không tự mất, nên phải có lifecycle dọn version cũ. Phản chứng: dung lượng bucket tăng đơn điệu dù số tệp không đổi.</li><li><strong>SCANNING thành trạng thái chết.</strong> Niềm tin sai: quét xong thì bản ghi tự sang READY. Nghe hợp lý vì đường thành công chạy đúng. Điều đúng: job quét cần timeout và một hàng đợi lỗi, nếu không bản ghi kẹt vĩnh viễn ở giữa. Phản chứng: hàng loạt bản ghi đứng ở SCANNING và người dùng thấy trạng thái “đang xử lý” mãi không thôi.</li></ul>",
  "tradeoff": "<p><strong>Được gì:</strong> byte không đi qua API nên không tốn băng thông hai lần và không chạm trần kích thước body của tầng trước; quyền ghi chỉ sống mười phút trên một key do server đặt; chỉ bản ghi <code>READY</code> mới được phục vụ.</p><p><strong>Mất gì:</strong> ba request thay vì một, kèm một trạng thái trung gian phải định nghĩa rõ và một worker dọn phải chạy đúng. Versioning tốn dung lượng gấp nhiều lần số tệp thật, và quét nội dung thêm độ trễ trước khi người dùng thấy tệp.</p><p><strong>Rủi ro:</strong> hạn ngắn đẩy lỗi sang nhóm người dùng mạng chậm, và <code>403</code> không nói cho client biết phải xin URL mới. Worker dọn chạy sai thời hạn là xoá object của một lời xác nhận đang trên đường tới.</p><p><strong>Vì sao vẫn đáng:</strong> đổi lại, một tệp chưa qua kiểm tra không bao giờ có URL đọc, và một URL bị lộ chỉ mở đúng một key trong mười phút.</p>",
  "alternatives": "<p><strong>Khi nào KHÔNG nên dùng:</strong> khi tệp nhỏ, hiếm, và không được phục vụ lại cho người khác.</p><ul><li><strong>Upload qua API trực tiếp:</strong> một request, không trạng thái trung gian, không object mồ côi; cái giá là byte đi qua server hai lần và chạm trần body.</li><li><strong>Presigned POST thay vì PUT:</strong> chọn khi cần S3 tự chặn kích thước bằng <code>content-length-range</code>; cái giá là form fields phức tạp hơn.</li><li><strong>Multipart upload:</strong> chọn khi tệp hàng trăm MB, vì tải lại đúng phần hỏng; cái giá là mỗi phần một lời gọi và phải quản lý vòng đời phiên.</li><li><strong>Không bật Versioning:</strong> chỉ chấp nhận được khi không có ghi đè nào xảy ra, và khi đó đừng xoá theo key — vì không có <code>VersionId</code> để nhắm đúng bản.</li></ul>",
  "observe": "<p><strong>Bốn tín hiệu, xếp theo thứ tự bạn nên xem trước.</strong></p><ul><li><strong>Khoảng cách giữa số object và số hàng READY.</strong> Đếm định kỳ cả hai; khoảng cách chính là số tệp không ai chủ, và nó phải tiến về 0 chứ không chỉ dao động.</li><li><strong>Số bản ghi PENDING quá hạn.</strong> Tăng đều nghĩa là bước xác nhận đang thất bại ở một tỉ lệ cố định, thường vì mạng di động hoặc vì endpoint confirm chậm.</li><li><strong>Tỉ lệ lệch giữa kích thước thật và kích thước khai.</strong> Ghi cả hai ở bước xác nhận. Khác 0 nghĩa là chữ ký đang thiếu một ràng buộc, và đây là tín hiệu bảo mật chứ không phải tín hiệu trải nghiệm.</li><li><strong>Số bản ghi đứng ở SCANNING quá lâu.</strong> Đây là hàng đợi quét bị nghẽn hoặc job chết, và người dùng đang thấy trạng thái chờ mà không ai xử lý.</li></ul>",
  "attacks": [{"q":"Tại sao trong hàm generate_presigned_url(ClientMethod='put_object') bạn không đưa luôn ContentLength vào Params để cấm người dùng đẩy file 5GB lên S3?","a":"<p><strong>Trả lời mẫu (30–60 giây):</strong> Vì <code>Content-Length</code> là forbidden request header: trình duyệt tự đặt nó từ body và JavaScript không được sửa, nên không có giá trị nào để ký. Chữ ký chỉ ràng buộc thứ đã nằm trong canonical request, nên kích thước nằm ngoài hợp đồng. Hai cách chặn thật: chuyển sang <code>generate_presigned_post</code> với điều kiện <code>content-length-range</code> để S3 tự ngắt, hoặc kiểm <code>ContentLength</code> ở bước confirm rồi xoá đúng version vi phạm.</p><p><strong>Lỗi hay mắc khi trả lời:</strong> nói \"thêm <code>ContentLength</code> vào <code>Params</code> là S3 chặn\" — cách nói đúng là với PUT phát ra từ trình duyệt, ràng buộc đó không ký được và cũng không thực thi được.</p>"},{"q":"Nếu tôi giảm thời gian sống (ExpiresIn) của Presigned PUT URL xuống còn 60 giây thì có ngăn được trò 'PUT ảnh sạch để qua kiểm tra rồi PUT đè file độc lên cùng key' không?","a":"<p><strong>Trả lời mẫu (30–60 giây):</strong> Không. Kẻ tấn công dùng script bắn hai lệnh PUT liên tiếp trong vài trăm mili-giây, nên hạn 600 giây hay 5 giây đều mở cùng một cửa sổ. Bản chất là tranh chấp kiểm-rồi-dùng: S3 không có cơ chế URL chỉ dùng một lần. Hai cách đóng cửa sổ: bật Versioning và ghim <code>VersionId</code> ngay khi bắt đầu quét, hoặc cấp quyền ghi vào một vùng cách ly rồi worker copy sang vùng không ai có URL ghi.</p><p><strong>Lỗi hay mắc khi trả lời:</strong> nói \"rút hạn là giảm rủi ro\" — cách nói đúng là rút hạn chỉ giảm thời gian URL bị lộ, không đóng được cửa sổ ghi đè.</p>"},{"q":"Khi bật S3 Bucket Versioning, nếu phát hiện file độc hại và gọi s3.delete_object(Bucket=..., Key=...) mà quên truyền VersionId thì chuyện gì xảy ra?","a":"<p><strong>Trả lời mẫu (30–60 giây):</strong> File độc vẫn nằm nguyên trong bucket. Trên bucket bật Versioning, lệnh xoá không kèm <code>VersionId</code> chỉ tạo thêm một delete marker đặt lên trên, còn phiên bản chứa nội dung vẫn nằm dưới và vẫn bị tính tiền. Muốn xoá thật phải truyền <code>VersionId</code> tường minh, cần quyền <code>s3:DeleteObjectVersion</code>, và nên cấu hình <code>NoncurrentVersionExpiration</code> để dọn các phiên bản bị bỏ rơi.</p><p><strong>Lỗi hay mắc khi trả lời:</strong> nói \"xoá xong là hết\" — cách nói đúng là delete marker chỉ ẩn object khỏi lần đọc thường, và mọi URL ghim version cũ vẫn tải được nội dung đó.</p>"},{"q":"Worker đã đọc 8 byte đầu tiên (Magic Bytes) và xác nhận đúng chữ ký của file PDF/PNG rồi, tại sao vẫn phải qua bước quét Virus và giữ trạng thái SCANNING?","a":"<p><strong>Trả lời mẫu (30–60 giây):</strong> Vì magic bytes và quét mã độc trả lời hai câu hỏi ở hai tầng. Tầng một chỉ xác nhận cấu trúc đầu tệp đúng định dạng đã khai, đủ để chặn trò đổi tên tệp thực thi thành ảnh mà không tốn công tải cả tệp. Tầng hai mới là nội dung: một PDF hợp lệ vẫn có thể nhúng mã khai thác ở trang thứ mười, một PNG hợp lệ vẫn có thể là polyglot hoặc bom giải nén. Nên phải quét toàn bộ, hoặc tái tạo lại ảnh, trước khi chuyển <code>READY</code>.</p><p><strong>Lỗi hay mắc khi trả lời:</strong> nói \"đúng magic bytes là tệp sạch\" — cách nói đúng là magic bytes chỉ kiểm 8 byte đầu, và nó không nói gì về phần thân.</p>"}],
  "anchor": "Presigned URL chỉ thực thi đúng những gì đã ký vào nó; thứ không ký chỉ là lời khai, không phải cam kết.",
  "say30": "Byte của tệp không đi qua API: Vue xin presigned URL, server tự sinh key, ký content type và hạn mười phút, rồi trình duyệt PUT thẳng lên S3. Vì vậy API không thấy nội dung nào, nên bước xác nhận phải đọc head_object để so kích thước thật, key và metadata của đúng version, khớp mới chuyển READY, lệch thì xoá và đánh dấu lỗi.",
  "say90": "[Nêu vấn đề (30s)]: Presigned URL là quyền ghi có hạn trên một key, không phải bằng chứng về nội dung. Nỗi đau đến từ ba phía cùng lúc: hạn được tính từ lúc ký nên người mạng chậm nhận 403, một lần xác nhận thất bại để lại object không ai chủ, và một URL đã cấp vẫn nhận được byte khác hẳn lời khai vì chữ ký không mang kích thước.\n\n[Cơ chế (45s)]: Server tự sinh key có tiền tố tenant, ghi bản ghi chờ trước khi ký, rồi ký PUT kèm content type và hạn ngắn. Trình duyệt PUT thẳng lên S3 nên API không thấy byte nào. Bước xác nhận đọc head_object để lấy kích thước thật, content type, VersionId và metadata, rồi so với bản ghi: khớp thì chuyển sang quét nội dung và chỉ sau đó mới READY, lệch thì xoá đúng version vừa đọc và đánh dấu lỗi. Versioning giữ object bất biến, để byte được quét và byte được phục vụ luôn là một.\n\n[Ranh giới (15s)]: Ba bước kéo theo một trạng thái trung gian phải định nghĩa rõ và một worker dọn dẹp phải chạy đúng; Versioning tốn chỗ; hạn ngắn chỉ dời lỗi sang người dùng mạng chậm.",
  "body": "<p><strong>Ví dụ chuyển giao.</strong> Một ứng dụng chat cho phép gửi ảnh đại diện 2 MB. Ở đây quét nội dung gần như vô nghĩa, vì ảnh được hiển thị lại qua một URL có hạn.</p><p>Rủi ro thật là người dùng A đọc được ảnh của người dùng B. Ràng buộc phải giữ là key có tiền tố tenant và mọi lần đọc đều qua một URL mới, không phải versioning.</p><p>Ngược lại, một hệ thống hoá đơn cho phép đính kèm PDF 40 MB. Ở đây chính nội dung là thứ nguy hiểm, nên trạng thái trung gian và bước quét mới là phần bắt buộc.</p><p>Câu hỏi luôn giống nhau: làm sao biết thứ trong bucket khớp với bản ghi. Mức thấp nhất là tin lời khai của client ở endpoint confirm, và mức đó sai vì client khai được bất cứ thứ gì. Mức giữa là đọc <code>head_object</code> rồi so kích thước và content type. Mức cao nhất là ghim <code>VersionId</code>, quét nội dung, rồi chỉ công bố sau khi quét xong.</p><p>Chọn mức nào là chọn theo thiệt hại khi sai, không theo số dòng code.</p>",
  "code": "# API: cấp presigned URL, tự đặt key, ràng buộc header lúc ký.\n@app.post(\"/uploads/presign\")\nasync def presign(body: PresignIn, user=Depends(current_user)):\n    # 413 là quá dung lượng, 415 là sai media type. Hai lỗi khác nhau nên\n    # phải tách: gộp một mã thì client không biết sửa gì.\n    if body.size > MAX_BYTES:\n        raise HTTPException(413, \"tệp vượt hạn mức\")\n    if body.kind not in ALLOWED:\n        # ALLOWLIST nằm ngay ở bước cấp URL, không đợi bước xác nhận mới\n        # từ chối: lúc cấp URL chưa có byte nào, đây là nơi duy nhất còn\n        # quyết định được loại tệp nào được cấp quyền ghi.\n        raise HTTPException(415, \"loại tệp không được hỗ trợ\")\n    key = f\"{user.tenant}/{body.kind}/{uuid4().hex}{ext_of(body.kind)}\"\n    # client không được chọn key, chỉ được dùng key này\n    url = s3.generate_presigned_url(\n        ClientMethod=\"put_object\",\n        Params={\n            \"Bucket\": BUCKET, \"Key\": key,\n            \"ContentType\": body.content_type,   # S3 tự từ chối request sai header\n            # KHÔNG đưa kích thước vào đây: Content-Length là forbidden request\n            # header, trình duyệt tự tính từ body nên nó không phải một ràng buộc\n            # mà người dùng thật có thể tuân theo. Hạn mức kiểm thật ở bước confirm.\n        },\n        ExpiresIn=600,                          # 10 phút là đủ\n    )\n    # GHI bản ghi ngay lúc cấp URL, version_id sẽ được ghim ở bước confirm.\n    uploads.insert(version_id=None, key=key, tenant=user.tenant,\n                   kind=body.kind, state=\"PENDING\")\n    return {\"url\": url, \"key\": key, \"expires_in\": 600}\n\n# Worker: magic bytes + quét virus, cách ly trước khi công bố.\n# kind là loại ĐÃ KHAI ở bước cấp URL, đọc từ bản ghi upload chứ không phải\n# từ client: đây là chuẩn để đối chiếu, vì URL có thể bị dùng lại cho\n# tệp khác.\ndef confirm(object_key: str, tenant: str, kind: str) -> None:\n    head = s3.head_object(Bucket=BUCKET, Key=object_key)\n\n    # URL presigned DÙNG LẠI ĐƯỢC nhiều lần cho tới hết hạn (600s), nên sau\n    # khi worker quét xong, client vẫn PUT lại được và ghi đè chính key này.\n    # Nếu quét và phục vụ đều chỉ theo key, byte được quét và byte được phục\n    # vụ là hai đối tượng khác nhau. Versioning đóng đối tượng thành\n    # MỘT version bất biến.\n    version_id = head[\"VersionId\"]\n\n    if head[\"ContentLength\"] > MAX_BYTES:      # kích thước S3 thật sự ghi\n        s3.delete_object(Bucket=BUCKET, Key=object_key, VersionId=version_id)\n        raise ValueError(\"tệp lớn hơn mức client khai\")\n\n    # ContentType trong head chỉ là header client gửi lên, không phải nội dung\n    # thật. Muốn sniff magic bytes phải tải vài byte đầu của chính object,\n    # và phải kèm VersionId để đọc ĐÚNG version vừa ghim.\n    magic = s3.get_object(\n        Bucket=BUCKET, Key=object_key,\n        VersionId=version_id, Range=\"bytes=0-7\")[\"Body\"].read()\n    if not sniff(magic, kind):\n        quarantine(object_key, version_id)   # đổi sang prefix không đọc được\n        raise ValueError(\"nội dung không khớp loại đã khai\")\n\n    # Sniff đạt chỉ là bằng chứng sơ bộ về ĐỊNH DẠNG, không phải quét mã độc.\n    # Bản ghi lúc này ở SCANNING, chưa READY.\n    uploads.set(object_key, state=\"SCANNING\")\n    if scanner.scan(object_key, version_id) == \"infected\":\n        quarantine(object_key, version_id)\n        raise ValueError(\"bị chặn virus\")\n\n    publish(object_key, tenant, version_id)  # chỉ bản ghi READY mới được đọc\n\n\n# Phục vụ: LUÔN kèm VersionId đã qua quét. Bỏ VersionId thì S3 trả về\n# bản mới nhất của key, tức là có thể là bản client đã ghi đè sau khi quét.\ndef serve_url(object_key: str, tenant: str) -> str:\n    row = uploads.one(tenant=tenant, key=object_key)\n    if row.state != \"READY\":\n        raise HTTPException(409, \"bản ghi chưa READY\")\n    return s3.generate_presigned_url(\n        ClientMethod=\"get_object\",\n        Params={\"Bucket\": BUCKET, \"Key\": object_key,\n                \"VersionId\": row.version_id},   # bắt buộc: bản đã quét\n        ExpiresIn=300,\n    )\n\n# Vue: xin URL, PUT thẳng lên S3, rồi mới báo API.\nasync function upload(file, kind) {\n  const { url, key } = await api.post(\"/uploads/presign\", {\n    kind, size: file.size, content_type: file.type,\n  });\n  // PUT thẳng: byte không qua API của bạn. Content-Type phải bằng đúng\n  // giá trị đã ký vào URL, nếu khác S3 tự từ chối request này.\n  await http.put(url, file, { headers: { \"Content-Type\": file.type } });\n  return api.post(\"/uploads/confirm\", { key });\n}",
  "codeNote": "<p><strong>Cách tệ so với cách tốt, nhìn từ khối code trên.</strong></p><ul><li><strong>Cách tệ:</strong> nhận <code>key</code> từ client và ký URL sống một ngày, nên client chọn được key trùng và ghi đè dữ liệu của tenant khác.</li><li><strong>Cách tốt:</strong> server tự sinh key dạng <code>uploads/{tenant}/{kind}/{uuid}</code>, nên quyền ghi bị giới hạn vào đúng một chỗ chưa ai dùng.</li><li><code>ExpiresIn=600</code> thay vì một ngày: cửa sổ dùng lại URL hẹp lại, và một URL bị lộ chỉ có giá trị trong mười phút.</li><li><code>ContentType</code> nằm trong <code>Params</code> là ràng buộc thật, vì S3 kiểm header đã ký; kích thước thì cố ý không đưa vào, vì <code>Content-Length</code> là forbidden request header.</li><li>Ghi bản ghi <code>PENDING</code> ngay trong hàm ký là thứ khiến bước confirm có gì để so, và khiến object mồ côi tìm được.</li></ul>",
  "sayIt": ["Tệp đi bằng ba request nhẹ: xin presigned URL, PUT thẳng byte lên S3, rồi xác nhận để ghi metadata; byte không bao giờ đi qua API của tôi nên không tốn băng thông hai lần và không chạm trần body của gateway.","Key do server sinh chứ không nhận từ client, vì nếu lấy key từ client thì bất kỳ ai giữ token đều có thể chọn key trùng và ghi đè dữ liệu của tenant khác.","Content-Type thì ký được nên tôi ký vào URL để S3 tự từ chối request sai header, còn kích thước thì không ràng buộc được bằng chữ ký trong một PUT vì Content-Length là forbidden request header mà trình duyệt tự đặt, nên tôi kiểm ở bước xác nhận bằng head_object so với số client đã khai.","URL có hạn 10 phút vì tôi không thu hồi riêng từng URL được, dù vẫn chặn được bằng cách gỡ quyền của danh tính đã ký; bucket private cộng presigned nghĩa là biết tên tệp cũng không đọc được.","Loại tệp tôi chặn ngay ở bước cấp URL với lỗi 415, vì lúc cấp URL thì chưa có byte nào mà đó lại là chỗ duy nhất còn quyết định được loại nào được cấp quyền ghi. Ở bước xác nhận tôi sniff magic bytes bằng get_object kèm Range, nhưng so với đúng loại tôi đã khai chứ không chỉ thuộc danh sách cho phép; sniff đạt chỉ đưa bản ghi sang SCANNING, và chỉ bước quét nội dung riêng chạy bất đồng bộ mới chuyển sang READY, tức là cách ly trước khi công bố."],
  "qids": ["G06","E09","E07","G11"],
  "refs": ["aws-s3-presigned","aws-s3","aws-s3-versioning","mdn-http-headers"]
},
{
  "provenance": ["Số liệu trong sự cố, dòng thời gian và cách làm ngây thơ là giả định để dựng kịch bản, không phải số đo từ một hệ thống thật.","Các khẳng định về visibility timeout, receipt handle, redrive policy và về tính nguyên tử của transaction PostgreSQL được đối chiếu với tài liệu chính thức trong refs; phần còn lại là mô hình suy ra từ chúng."],
  "id": "L21",
  "stage": 4,
  "stageTitle": "Chặng 4 — Nối hai mảng",
  "title": "Outbox: vì sao ghi cơ sở dữ liệu và gửi message lệch nhau, và chỗ nào vá được",
  "goal": "Trong bài này bạn phải chỉ ra được hai cách mà một message trên hàng đợi có thể lệch khỏi hàng đã commit trong cơ sở dữ liệu, nói rõ outbox vá đúng cách nào trong hai cách đó, và giải thích vì sao outbox không cứu được cách còn lại.",
  "bridge": "Bài trước chốt rằng API chỉ cấp quyền ghi rồi xác nhận thứ đã nằm trong bucket, còn việc nặng chạy sau đó. Bài này lo phần “sau đó”: làm sao một hàng đã commit chắc chắn sinh ra một message, và làm sao một message chạy hai lần vẫn chỉ cho ra một kết quả.",
  "buildsOn": ["L06","L11"],
  "incident": "<p><strong>Không có thứ này thì đau ở đâu?</strong> Giả sử đội vừa đẩy việc nặng sang worker: tải tệp 5 MB từ S3, quét nội dung, gửi hoá đơn. <code>visibility timeout</code> (thời gian message bị ẩn khỏi hàng đợi sau khi một worker nhận) để 30 giây vì đó là giá trị mặc định, trong khi thời gian xử lý p99 khoảng 45 giây.</p><p>Một đợt 10.000 tệp đổ vào trong hai mươi phút, không cảnh báo nào bắn. Đến chiều, kế toán mang một bảng tính: 340 khách nhận hai hoá đơn cho cùng một lần upload, và log worker có đúng hai dòng cho cùng một <code>message_id</code>, cách nhau 30 giây.</p><p>Dashboard vẫn xanh vì message đang xử lý nằm ở trạng thái ẩn. Chỉ số duy nhất xấu đi là độ tuổi của message cũ nhất.</p><p>Gốc của cả hai chuyện là <code>dual-write</code> (lỗi ghi đồng thời vào hai hệ thống khác nhau không có giao dịch chung): ghi cơ sở dữ liệu và gửi message là hai việc, ở hai hệ thống, không có transaction chung.</p>",
  "askFirst": ["Vì sao một message có thể được hai worker cùng xử lý mà log không có dòng lỗi nào?","Vì sao số message trong hàng đợi trông thấp trong khi hệ thống đang tắc dần?","Nếu tăng số worker lên gấp ba, số hoá đơn gửi trùng sẽ tăng hay giảm?"],
  "predict": {"q":"Visibility timeout là 30 giây. Worker A nhận message ở giây 0, xử lý xong ở giây 45 và gọi xoá bằng receipt handle nhận được ở giây 0. Ở giây 30 message đã được giao cho worker B. Lời gọi xoá của A có hiệu lực không, và khách nhận mấy hoá đơn?","a":"<p>Lời gọi xoá của A không có hiệu lực trên bản đang thuộc B. <code>delete_message</code> xoá theo receipt handle của lần nhận, không theo <code>message_id</code>; khi lease hết hạn ở giây 30, phiếu nhận của A hết giá trị và B nhận một phiếu mới, nên lời gọi của A bị từ chối hoặc chỉ tác động lên một bản không còn tồn tại. Vì vậy B vẫn xử lý tiếp và khách nhận hai hoá đơn — trừ khi worker idempotent: nếu bước nghiệp vụ chèn khoá <code>message_id</code> trong cùng transaction, lần chạy của B đụng khoá và chỉ xác nhận rồi thoát, nên khách nhận đúng một hoá đơn. Nhánh còn lại: nếu A xoá trước khi lease hết thì B không bao giờ nhận, và trường hợp hai lần chạy không xảy ra — đó là lý do phải đặt visibility lớn hơn thời gian xử lý thay vì trông vào việc xoá.</p>"},
  "naive": "<p><strong>Cách tệ (làm theo phản xạ):</strong> coi visibility timeout là khoá độc quyền, và coi message do hệ thống mình tạo ra là message không bao giờ hỏng.</p><ul><li><strong>Niềm tin:</strong> message đã bị ẩn khỏi hàng đợi thì không ai khác nhận được, nên xử lý xong chỉ cần xoá; và JSON do chính API ghi ra thì luôn parse được.</li><li><strong>Vì sao nghe hợp lý:</strong> ở mười message thử nghiệm, mỗi message chạy đúng một lần, không có hoá đơn trùng, và không có message nào hỏng định dạng.</li><li><strong>Chỗ chết:</strong> ẩn là một hợp đồng thuê có hạn chứ không phải khoá, nên lease hết mà worker còn chạy thì message hiện lại; và message hỏng định dạng thì hỏng ở mọi lần thử, nên để nó quay vòng chỉ đốt worker.</li></ul>",
  "naiveCode": "import json\n\n# ❌ Cách làm sai phổ biến: queue tạo với VisibilityTimeout = 30 (giá trị mặc định).\n\ndef handle(raw: bytes, receipt: str) -> None:\n    # json.loads nằm NGOÀI try: JSON hỏng ném thẳng ra ngoài, không bao giờ chạm nhánh lỗi vĩnh viễn.\n    msg = json.loads(raw)\n\n    # Việc nặng mất khoảng 45 giây, trong khi visibility timeout chỉ 30 giây.\n    do_heavy_work(msg)\n\n    # Xoá sau khi xong, bằng receipt handle đã hết hạn ở giây thứ 30.\n    queue.delete_message(receipt)",
  "naiveOut": "<p>Ở mười message thử nghiệm mọi thứ đều đúng: mỗi message chạy một lần, không có hoá đơn trùng. Đó là lý do code được merge.</p><p> Ở 10.000 message trong đợt cao điểm, log worker có hai dòng cho cùng một <code>message_id</code> cách nhau đúng 30 giây, vì tới hạn visibility message hiện lại và worker khác nhận. Chiều hôm đó, 340 khách hàng nhận hai hoá đơn cho cùng một lần upload. </p><p> Đi kèm, một message JSON hỏng không bao giờ chạm nhánh lỗi vĩnh viễn: nó ném exception ngay ở dòng parse, worker báo lỗi, SQS đếm thêm một lần nhận, và message quay lại hàng đợi chờ vòng thử kế tiếp. Độ tuổi message cũ nhất vượt 40 phút trong khi số message hiển thị vẫn thấp, nên dashboard xanh hoàn toàn.</p>",
  "timeline": [["13:00:00","Đợt 10.000 tệp bắt đầu vào hàng đợi; độ tuổi message cũ nhất là 2 giây."],["13:00:05","Worker A nhận một message và bắt đầu tải tệp 5 MB."],["13:00:35","Visibility timeout 30 giây hết hạn; message hiện lại trong hàng đợi."],["13:00:36","Worker B nhận đúng message đó và bắt đầu cùng thao tác nghiệp vụ."],["13:01:20","Worker B xử lý xong và gửi hoá đơn thứ hai cho cùng một khách."],["14:30:00","Độ tuổi message cũ nhất là 41 phút trong khi số message hiển thị vẫn thấp."]],
  "rootCause": "<p>Hai nguyên nhân độc lập, và chỉ một trong hai được outbox vá.</p><ul><li>Visibility timeout là hợp đồng thuê có hạn, không phải khoá: hết hạn mà worker chưa xoá thì message hiện lại và worker khác nhận.</li><li>Ghi cơ sở dữ liệu và gửi message không có transaction chung, nên commit xong mà gửi lỗi là mất việc, còn gửi xong mà commit lỗi là message trỏ tới hàng không tồn tại.</li><li>Message hỏng định dạng bị đối xử như lỗi tạm thời, nên nó quay vòng cho tới hết hạn lưu trữ và không bao giờ tới được hàng đợi lỗi.</li></ul>",
  "concept": "Ghi cơ sở dữ liệu và gửi message là hai hệ thống không có transaction chung, nên outbox ghi message như hàng trong cùng transaction với nghiệp vụ rồi để một relay đẩy lên hàng đợi; outbox không cứu được việc giao trùng, nên worker phải idempotent.",
  "mechanism": "<p><strong>Ví von đời thường:</strong> ghi cơ sở dữ liệu rồi gửi message giống viết hoá đơn vào sổ rồi mới chạy ra bưu điện — ngã trên đường thì sổ đã có hoá đơn mà thư chưa đi. Outbox là việc dán luôn con tem vào trang sổ, để ai mở sổ ra cũng biết còn thư chưa gửi. Giới hạn: người đưa thư chỉ giao đúng một lần, còn relay có thể gửi cùng một message hai lần.</p><pre><code>API ──một transaction──→ [ orders + outbox ]  (cùng commit)\n                                │\n                                ▼\n                        relay: đọc hàng chưa gửi\n                                │\n                    ┌───────────┴────────────┐\n                    ▼                        ▼\n              send lên hàng đợi        đánh dấu đã gửi\n                    │                  (transaction riêng)\n                    ▼                        │\n                 worker ◄────────────────────┘\n                    │\n                    └─→ chèn message_id + việc nghiệp vụ (cùng transaction)</code></pre><ol><li><strong>Bước 1 — Transaction chỉ bao trùm một hệ thống:</strong> commit của cơ sở dữ liệu không rollback được hàng đợi, và hàng đợi không giữ message lại chờ commit, nên giữa hai lời gọi luôn có một khoảng thời gian.</li><li><strong>Bước 2 — Trong khoảng đó có đúng hai chiều lệch:</strong> ghi thành công mà gửi lỗi thì mất việc; gửi thành công mà commit lỗi thì có message trỏ tới hàng không tồn tại.</li><li><strong>Bước 3 — Ghi message như một hàng dữ liệu:</strong> <code>transactional outbox</code> (bảng hộp thư đi nằm cùng giao dịch database với dữ liệu nghiệp vụ) biến việc gửi thành hệ quả của commit, nên chiều mất biến mất.</li><li><strong>Bước 4 — Cái còn lại là trùng:</strong> relay gửi xong rồi chết trước khi đánh dấu thì lần sau gửi lại, nên chỉ consumer idempotent mới làm lần gửi thừa thành vô hại.</li></ol>",
  "visuals": [{"id": "flow-outbox-worker", "question": "Vì sao một hàng đã commit có thể không có message, và vì sao một message có thể chạy hai lần — outbox vá chỗ nào?", "focus": "Outbox"}],
  "failureModes": "<p>Bốn kiểu hỏng của chính cách sửa này.</p><ul><li><strong>Bảng khoá phình không kiểm soát.</strong> Niềm tin sai: mỗi message một hàng khoá là rẻ. Nghe hợp lý vì một hàng chỉ vài chục byte. Điều đúng: số hàng bằng số message mãi mãi, nên cần TTL hoặc tiến trình dọn theo thời hạn. Phản chứng: thời gian chèn khoá tăng dần theo tuần dù lưu lượng không đổi, và bảng khoá lớn hơn bảng nghiệp vụ.</li><li><strong>Gia hạn visibility tưởng là cài một lần.</strong> Niềm tin sai: đã gia hạn thì message không hiện lại nữa. Nghe hợp lý vì lần gia hạn đó có tác dụng thật. Điều đúng: giá trị gia hạn chỉ có hiệu lực cho lần nhận hiện tại, nên logic phải chạy lại từ đầu ở mỗi lần nhận. Phản chứng: log có hai lần chạy cho cùng một message, cách nhau đúng bằng timeout gốc của hàng đợi.</li><li><strong>Message độc đốt worker.</strong> Niềm tin sai: cứ để nó thử lại, rồi nó sẽ tự vào hàng đợi lỗi. Nghe hợp lý vì hàng đợi có cơ chế redrive. Điều đúng: redrive chỉ hoạt động khi có redrive policy cùng số lần nhận tối đa; không cấu hình thì message quay lại cho tới hết hạn lưu trữ và chiếm worker suốt thời gian đó. Phản chứng: một message duy nhất chiếm một worker liên tục trong nhiều giờ, và số lần nhận của nó tăng đều.</li><li><strong>Hàng đợi lỗi thành thùng rác.</strong> Niềm tin sai: message đã vào hàng đợi lỗi là an toàn. Nghe hợp lý vì nó không còn quay vòng. Điều đúng: hàng đợi lỗi cũng có hạn lưu trữ, và không có cảnh báo khi độ sâu khác 0 thì message im lặng biến mất. Phản chứng: độ sâu hàng đợi lỗi về 0 mà không ai xử lý gì, và những đơn đó không bao giờ có kết quả.</li></ul>",
  "tradeoff": "<p><strong>Được gì:</strong> một hàng đã commit chắc chắn sinh ra một message, nên không còn đơn đã trừ tiền mà không có hoá đơn; việc gửi thành bước có thể thử lại; giao trùng trở thành vô hại thay vì phải đi đền khách.</p><p><strong>Mất gì:</strong> thêm một bảng, một relay chạy liên tục và một bảng khoá phải dọn. Độ trễ tăng thêm một nhịp quét: relay chạy mỗi phút thì mọi việc chậm thêm tới một phút.</p><p><strong>Rủi ro:</strong> visibility dài có giá ngược lại — worker chết thật thì message nằm ẩn lâu hơn trước khi được giao lại. Và bảng đã xử lý không được dọn sẽ phình mãi.</p><p><strong>Vì sao vẫn đáng:</strong> khi mất một message là mất tiền hoặc mất niềm tin của khách, đổi một nhịp quét lấy việc không mất message là lời.</p>",
  "alternatives": "<p><strong>Khi nào KHÔNG nên dùng:</strong> khi việc không quan trọng, hoặc khi message nằm trong chính cơ sở dữ liệu.</p><ul><li><strong>Thông báo đẩy trong ứng dụng:</strong> bỏ một cái cũng không sao thì gửi thẳng sau commit đơn giản hơn nhiều.</li><li><strong>Message nằm trong cùng cơ sở dữ liệu:</strong> một transaction là đủ, thêm outbox chỉ là thêm một tầng.</li><li><strong>Đọc thay đổi từ write-ahead log:</strong> chọn khi không muốn thêm bảng outbox; cái giá là thêm một hệ thống phải vận hành.</li><li><strong>Gọi trực tiếp worker qua API nội bộ có thử lại:</strong> chỉ hợp lý khi khối lượng nhỏ và cần thấy kết quả ngay; cái giá là mất tính chịu lỗi, tức là tự viết lại một hàng đợi tồi hơn.</li></ul>",
  "observe": "<p><strong>Bốn tín hiệu, và cái quan trọng nhất không phải cái mọi người nghĩ tới.</strong></p><ul><li><strong>Độ tuổi của message cũ nhất.</strong> Đây là chỉ số tắc thật: nó tăng ngay cả khi số message hiển thị thấp, vì message đang xử lý nằm ở trạng thái ẩn. Cảnh báo nên đặt trên chỉ số này, không phải trên số message.</li><li><strong>Bẫy của chính chỉ số đó.</strong> Message bị nhận lại quay về cuối hàng, nên độ tuổi cũ nhất có thể tụt xuống trong khi hệ thống vẫn hỏng; phải đọc kèm độ sâu hàng đợi lỗi mới không kết luận sớm rằng sự cố đã qua.</li><li><strong>Số message hiển thị đọc cùng số message đang ẩn.</strong> Hiển thị thấp cộng đang ẩn cao nghĩa là worker chạy hết công suất, không phải hàng đợi rảnh.</li><li><strong>Độ sâu hàng đợi lỗi.</strong> Cảnh báo khi khác 0, và phải có người thật xem, vì đó là nơi những đơn không có kết quả đang nằm chờ hết hạn lưu trữ.</li></ul>",
  "attacks": [{"q":"Bạn nói VisibilityTimeout của SQS phải lớn hơn thời gian xử lý của Worker. Vậy nếu tác vụ xử lý tệp có lúc mất 10 giây, có lúc mất 4 phút thì đặt VisibilityTimeout bao nhiêu?","a":"<p><strong>Trả lời mẫu (30–60 giây):</strong> Đặt theo p99 cộng biên an toàn, rồi xử lý phần đuôi bằng cách gia hạn chủ động. Ví dụ đặt 60 giây và cho một luồng phụ gọi <code>change_message_visibility</code> mỗi 20 giây khi tác vụ còn chạy. Đặt tĩnh quá dài có giá ngược lại: worker chết ở giây thứ hai thì message bị ngâm ẩn suốt 30 phút mới được giao lại, nên thời gian phục hồi rất tệ.</p><p><strong>Lỗi hay mắc khi trả lời:</strong> nói \"đặt bằng thời gian xử lý tối đa là xong\" — cách nói đúng là thời gian tối đa không đo được, nên phải dùng p99 cộng gia hạn nhịp tim.</p>"},{"q":"Tại sao trong log ghi rõ Worker thứ nhất đã gọi queue.delete_message() không báo lỗi gì, mà bản tin đó vẫn xuất hiện ở Worker thứ hai và chạy lặp lại?","a":"<p><strong>Trả lời mẫu (30–60 giây):</strong> Vì lúc worker một xoá thì lease đã hết hạn và message đã được giao cho worker hai kèm một <code>ReceiptHandle</code> mới. Lệnh xoá không xoá theo <code>MessageId</code> mà theo receipt handle của lần nhận đó, nên receipt handle cũ không còn giá trị. Kết luận: <code>delete_message</code> không bao giờ ngăn được việc chạy trùng; sự đúng đắn phải nằm ở bảng khoá trong cùng transaction của worker.</p><p><strong>Lỗi hay mắc khi trả lời:</strong> nói \"xoá không lỗi thì message đã bị xoá\" — cách nói đúng là xoá thành công chỉ nghĩa là receipt handle đó còn hiệu lực.</p>"},{"q":"Triển khai bảng Transactional Outbox nghe phức tạp vì phải có tiến trình quét (Poller/Relay). Tại sao không cho API gửi thẳng sqs.send_message() trước rồi mới gọi db.commit() ngay dòng dưới cho đơn giản?","a":"<p><strong>Trả lời mẫu (30–60 giây):</strong> Vì gửi trước rồi commit tạo ra hai thảm hoạ ngược chiều. Một, worker có thể nhận message trong vài chục mili-giây, nhanh hơn lúc commit ghi xong, nên nó truy vấn và không thấy đơn. Hai, nếu commit thất bại sau khi message đã bay đi thì message trỏ tới một đơn không tồn tại, và worker vẫn trừ kho, vẫn gửi hoá đơn. Outbox ghi cả hai thứ trong một transaction ACID nên không có khoảng thời gian đó.</p><p><strong>Lỗi hay mắc khi trả lời:</strong> nói \"commit nhanh nên gần như cùng lúc\" — cách nói đúng là thứ tự hai hệ thống không được bảo đảm, và \"gần như\" không phải một bảo đảm.</p>"},{"q":"Ở trong Worker, thay vì dùng INSERT INTO processed_messages bắt lỗi trùng khóa chính, tôi viết câu lệnh SELECT kiểm tra xem đã xử lý chưa rồi mới chạy (if not exists -> process) có được không?","a":"<p><strong>Trả lời mẫu (30–60 giây):</strong> Không. Đọc-kiểm-rồi-làm thủng ngay khi có hai worker chạy song song: ở mức cô lập mặc định, cả hai cùng <code>SELECT</code> ở mili-giây thứ 0, cả hai cùng thấy chưa có, và cả hai cùng trừ tiền. Cách duy nhất là để ràng buộc nguyên tử làm trọng tài: <code>INSERT</code> vào bảng có khoá chính trên <code>message_id</code> trong cùng transaction với việc nghiệp vụ, worker thứ hai nhận <code>UniqueViolation</code> và chỉ xác nhận message.</p><p><strong>Lỗi hay mắc khi trả lời:</strong> nói \"SELECT rồi INSERT trong cùng transaction là an toàn\" — cách nói đúng là chỉ ràng buộc khoá mới chặn được hai bên cùng lọt qua phép kiểm.</p>"}],
  "anchor": "Số message nói bạn đang bận, độ tuổi message nói bạn đang tắc.",
  "say30": "SQS giao ít nhất một lần, nên cùng một message có thể chạy hai lần và worker phải idempotent. Tôi ghi outbox cùng transaction với nghiệp vụ, rồi một relay đẩy lên bằng FOR UPDATE SKIP LOCKED. Chống chạy trùng bằng khoá chính chèn cùng transaction, không đọc trước rồi ghi sau. Visibility timeout là lease nên tôi đặt theo p99 và gia hạn định kỳ; để 30 giây trong khi xử lý 45 giây là 340 khách nhận hai hoá đơn.",
  "say90": "[Nêu vấn đề (30s)]: Gửi message không nằm trong transaction PostgreSQL nên có hai chỗ lệch: commit xong mà gửi thất bại thì đơn đã trừ tiền không có hoá đơn, gửi xong mà commit thất bại thì message trỏ tới hàng không tồn tại. Hàng đợi lại giao ít nhất một lần, nên một việc có thể chạy hai lần: 340 khách nhận hai hoá đơn vì visibility 30 giây ngắn hơn xử lý 45 giây.\n\n[Cơ chế (45s)]: Outbox ghi hàng nghiệp vụ và hàng message trong cùng một transaction, nên cả hai cùng có hoặc cùng không. Một relay đọc các hàng chưa gửi bằng FOR UPDATE SKIP LOCKED rồi đẩy lên và đánh dấu đã gửi; gửi xong mà chết trước khi đánh dấu thì lần sau gửi lại, nên vẫn trùng. Vì vậy worker chèn message_id vào bảng đã xử lý trong cùng transaction, để khoá chính làm trọng tài khi hai worker chạy song song. Visibility timeout đặt theo p99 và gia hạn.\n\n[Ranh giới (15s)]: Outbox không cứu được việc giao trùng và không cho thứ tự; nó thêm một bảng, một relay liên tục và một bảng khoá phải dọn, còn hàng đợi lỗi vẫn cần người đọc.",
  "body": "<p><strong>Ví dụ chuyển giao.</strong> Hệ thống xuất hoá đơn sau thanh toán, đỉnh 200 đơn mỗi phút. FastAPI commit đơn rồi gọi gửi message ngay, nên khi mạng chập chờn có 19 đơn đã trừ tiền mà không bao giờ có hoá đơn.</p><p>Song song, worker xử lý 45 giây nhưng visibility để mặc định 30 giây, nên 340 khách nhận hai hoá đơn. Hai triệu chứng, hai nguyên nhân khác nhau, và chỉ một trong hai do outbox vá.</p><p>Cách áp dụng: ghi outbox cùng transaction với đơn, relay đẩy lên hàng đợi bằng <code>SKIP LOCKED</code>. Đặt visibility theo p99 cộng biên an toàn, chèn khoá <code>message_id</code> trong transaction nghiệp vụ, và gửi message hỏng định dạng sang hàng đợi lỗi.</p><p>Ba dấu hiệu để nhận ra mình đang ở tình huống nào. Cùng một <code>message_id</code> xuất hiện hai lần cách nhau đúng bằng visibility timeout: lease hết hạn, phải tăng visibility và kiểm khoá chống trùng. Đơn đã commit mà không có message: việc gửi nằm ngoài transaction, phải đưa qua outbox. Số message hiển thị thấp nhưng độ tuổi message cũ nhất tăng: message đang ẩn hoặc quay vòng lỗi.</p>",
  "code": "# ✅ Cách làm chuẩn: worker idempotent, tách lỗi tạm thời và lỗi vĩnh viễn.\ndef handle(raw: bytes, receipt: str) -> None:\n    # 1. Parse JSON trong try RIÊNG: JSON hỏng là lỗi vĩnh viễn, phải vào DLQ trước khi xoá bản gốc.\n    try:\n        msg = json.loads(raw)\n    except json.JSONDecodeError:\n        dlq.send_message(MessageBody=raw.decode())\n        queue.delete_message(ReceiptHandle=receipt)\n        return\n\n    # 2. Khoá nghiệp vụ nằm TRONG CÙNG transaction với việc nghiệp vụ.\n    try:\n        with db.atomic() as c:\n            c.execute(\"INSERT INTO processed_messages (id) VALUES (%s)\",\n                      (msg[\"message_id\"],))         # trùng khoá chính = đã xử lý\n            do_heavy_work(c, msg)\n    except UniqueViolation:\n        # Lần chạy trước đã commit xong: đây là lần giao thừa, xác nhận rồi thôi.\n        queue.delete_message(ReceiptHandle=receipt)\n        return\n    except TransientError:\n        # Lỗi hạ tầng: gia hạn visibility để message quay lại đúng lúc.\n        queue.change_message_visibility(ReceiptHandle=receipt, VisibilityTimeout=120)\n        raise\n\n    queue.delete_message(ReceiptHandle=receipt)      # chỉ xoá khi đã thành công",
  "codeNote": "<p><strong>Cách tệ so với cách tốt, nhìn từ khối code trên.</strong></p><ul><li><strong>Cách tệ:</strong> <code>json.loads</code> nằm ngoài <code>try</code>, nên message hỏng định dạng ném thẳng ra ngoài và quay vòng mãi; và <code>delete_message</code> chạy bằng một receipt handle đã hết hạn ở giây thứ 30.</li><li><strong>Cách tốt:</strong> parse trong <code>try</code> riêng, hỏng thì chép sang hàng đợi lỗi rồi mới xoá bản gốc — vì xoá không tự chuyển message đi đâu cả.</li><li><code>INSERT INTO processed_messages</code> nằm trong cùng transaction với <code>do_heavy_work</code>: hai thứ cùng sống hoặc cùng chết, nên không có khoảng trống giữa \"đã ghi khoá\" và \"đã gửi hoá đơn\".</li><li>Nhánh <code>UniqueViolation</code> chỉ xác nhận message, không làm lại việc nặng — đó là chỗ biến lần giao thừa thành vô hại.</li><li><code>change_message_visibility</code> tách lỗi hạ tầng khỏi lỗi vĩnh viễn, để message quay lại sau thay vì bị đốt hết số lần thử.</li></ul>",
  "sayIt": ["Gửi message SQS và commit PostgreSQL là hai hành động riêng, không cùng transaction; tôi chọn outbox khi việc không được phép mất, chọn gửi trước rồi commit khi việc chạy lại được vô hại.","Outbox là chèn hàng trong cùng transaction với hàng nghiệp vụ, một tiến trình quét bằng FOR UPDATE SKIP LOCKED đẩy lên SQS, và toàn bộ quét phải nằm trong transaction vì khoá chỉ giữ trong transaction.","SQS bảo đảm ít nhất một lần nên worker phải idempotent; tôi chống chạy trùng bằng chèn khoá processed_messages trong cùng transaction với việc nghiệp vụ, không bằng đọc trước rồi ghi sau.","Visibility timeout là lease chứ không phải lock; tôi đặt theo p99 thời gian xử lý cộng biên an toàn và gia hạn định kỳ, vì để 30 giây trong khi xử lý 45 giây thì message hiện lại và worker khác nhận cùng một việc.","Lỗi tạm thời tôi gia hạn visibility để message quay lại; lỗi vĩnh viễn như JSON hỏng tôi parse trong try riêng, gửi một bản sang DLQ rồi mới xoá, vì xoá không tự chuyển message sang DLQ và DLQ chỉ hoạt động khi queue có redrive policy với maxReceiveCount.","Phía client cập nhật trạng thái bằng polling hoặc SSE, và tôi cảnh báo trên độ tuổi message cũ nhất chứ không phải số message, vì số message thấp chỉ là worker đang chạy hết công suất, không phải hệ thống ổn."],
  "qids": ["E07","G10","G11","F09"],
  "refs": ["aws-sqs-visibility","aws-sqs-dlq","pg-transactions","pg-upsert"]
},
{
  "provenance": ["Số liệu trong sự cố, dòng thời gian và cách làm ngây thơ là giả định để dựng kịch bản, không phải số đo từ một hệ thống thật.","Các khẳng định về Cache-Control, immutable, Origin Access Control, Block Public Access và OIDC được đối chiếu với tài liệu chính thức trong refs; phần còn lại là mô hình suy ra từ chúng."],
  "id": "L22",
  "stage": 4,
  "stageTitle": "Chặng 4 — Nối hai mảng",
  "title": "Deploy: vì sao index.html cũ trỏ vào tệp JS đã xoá, và rollback đúng phải là gì",
  "goal": "Trong bài này bạn phải giải thích được vì sao một người dùng đang mở trang lại nhận màn hình trắng ngay sau một lần deploy sạch, bằng cách chỉ ra hai chính sách cache khác nhau cho hai loại tệp, và nói được hai thứ phải có sẵn trước khi deploy để rollback chỉ còn là một thao tác đổi con trỏ.",
  "bridge": "Bài trước chốt rằng việc nặng chạy sau khi commit, và cái giá của nó là một bảng phải dọn. Bài này đưa cả hệ thống đó ra production: một lần deploy đổi cả giao diện lẫn cấu trúc bảng, nên câu hỏi không còn là code đúng hay sai, mà là người dùng đang cầm bản cũ sẽ gặp gì và bạn lùi lại trong bao lâu.",
  "buildsOn": ["L18","L19","L20","L21"],
  "incident": "<p><strong>Không có thứ này thì đau ở đâu?</strong> Giả sử đội deploy bản 2.0 lúc 22 giờ. Bản build gồm một <code>index.html</code> và vài tệp JS có hash trong tên; tất cả đẩy lên cùng một bucket S3, phục vụ qua CloudFront, và bucket đặt đúng một chính sách cache 24 giờ cho mọi tệp.</p><p>22:04, pipeline chạy <code>aws s3 sync dist/ s3://... --delete</code>. Tệp JS của bản 1.9 bị xoá ngay. Người dùng nào đã tải trang trong 24 giờ trước đó vẫn còn <code>index.html</code> cũ trong máy, và tệp đó trỏ tới JS vừa bị xoá: họ nhận <code>404</code> rồi màn hình trắng.</p><p>Sáng hôm sau khoảng 8% người dùng báo lỗi, trong khi máy của đội mở cửa sổ ẩn danh vẫn thấy trang lên bình thường — vì cửa sổ đó không có bản lưu nào.</p><p>Đội thử lùi lại bằng revert commit rồi cho pipeline build lại: hash ra khác, mất 40 phút, và trong suốt thời gian đó nhóm người dùng kia vẫn thấy trang trắng.</p>",
  "askFirst": ["Vì sao người dùng đã tải trang từ hôm trước lại thấy màn hình trắng, trong khi máy của bạn mở trang vẫn bình thường?","Điều gì có thể khiến một bản build lại từ đúng commit cũ vẫn không giống bản đã chạy tuần trước?","Vì sao một bucket không cho ai truy cập vẫn phục vụ được trang cho cả internet, và thứ gì đứng ra bảo lãnh cho việc đó?"],
  "predict": {"q":"Chính sách cache đã đặt đúng: tệp có hash là <code>max-age=31536000, immutable</code>, còn <code>index.html</code> là <code>no-cache</code>. Pipeline đẩy asset trước rồi mới đẩy index. Một người dùng đã mở tab từ trước bấm tải lại. Trình duyệt lấy <code>index.html</code> từ đâu, và còn nhánh nào khiến trang vẫn trắng dù chính sách đúng?","a":"<p>Trình duyệt gửi điều kiện <code>If-None-Match</code> vì index.html là no-cache: nội dung chưa đổi thì nhận 304 và dùng bản đã lưu, còn vừa promote thì nhận 200 với index mới. Vì index mới chỉ trỏ tới tệp có hash đã lên từ trước, trang lên bình thường — đây là nhánh chính. Nhánh xấu vẫn còn: nếu pipeline đẩy index trước khi asset lên xong, hoặc có bước xoá asset của bản cũ, thì index mới trỏ vào tệp chưa có và người dùng nhận 404, nghĩa là no-cache chỉ cứu được khi thứ tự đẩy đúng và asset cũ không bị xoá. Nhánh thứ ba: tab đang mở vẫn chạy JS cũ và gọi một route mà bản mới đã đổi; ở đây không có màn hình trắng, chỉ có lỗi API, vì JS cũ vẫn nằm trong bộ nhớ tab.</p>"},
  "naive": "<p><strong>Cách tệ (làm theo phản xạ):</strong> coi mọi tệp của một bản build là cùng loại, và coi bản build là thứ dựng lại được bất cứ lúc nào.</p><ul><li><strong>Niềm tin:</strong> cả bucket dùng một chính sách cache là đủ, và muốn lùi lại thì revert commit rồi build lại.</li><li><strong>Vì sao nghe hợp lý:</strong> trên máy đội, mở tab mới thì trang luôn lên đúng bản mới nhất, và build lại từ commit cũ cho ra bản chạy được — cả hai đều đúng.</li><li><strong>Chỗ chết:</strong> <code>index.html</code> là tệp duy nhất không có hash trong tên, nên nó bị cache y như tệp có hash và trỏ vào JS mà bước <code>--delete</code> vừa xoá; còn build lại phụ thuộc registry tại thời điểm build.</li></ul>",
  "naiveCode": "// ❌ Cách làm sai phổ biến: bucket public, cache đồng nhất, deploy bằng tay.\n// 1. Bucket policy cho Principal * và action s3:GetObject:\n//    CloudFront đọc được, nhưng Internet cũng đọc trực tiếp được qua URL S3.\n// 2. Cache-Control mặc định cho mọi file:\n//    index.html sống một ngày cùng TTL với app.a1b2c3.js, nên HTML cũ trỏ vào JS đã xoá.\n// 3. Deploy bằng tay, không đánh số artifact:\n//    rollback thành đoán file nào thuộc bản cũ.",
  "naiveOut": "Ngày đầu mọi thứ xanh vì đội luôn mở tab mới, và bản build nào cũng chạy được trên máy mình. Sau đợt deploy thứ hai, một bộ phận người dùng cầm index.html cache một ngày tải trang trắng, vì tệp JS mà nó trỏ tới đã bị bước --delete xoá. Kiểm tra bảo mật phát hiện tệp trong bucket đọc được trực tiếp qua URL S3 vì bucket mở public. Khi cần lùi lại, pipeline build lại từ commit cũ nhưng ra hash khác và kéo theo một thư viện vừa lên bản mới, nên mất bốn mươi phút mới có bản chạy được.",
  "timeline": [["22:00","Pipeline đẩy toàn bộ thư mục dist lên bucket, và bucket áp một chính sách cache 24 giờ cho mọi tệp."],["22:04","Bước <code>--delete</code> xoá tệp JS của bản 1.9 khỏi bucket."],["22:05","Người dùng còn giữ <code>index.html</code> cũ tải lại trang và nhận 404 cho tệp JS vừa bị xoá."],["08:30","Khoảng 8% người dùng vào trang báo màn hình trắng trong buổi sáng."],["09:10","Đội revert commit và cho pipeline build lại; bản dựng ra hash khác và kéo theo một thư viện vừa lên bản mới."],["09:50","Bản chạy được sau 40 phút, lâu hơn nhiều so với việc trỏ lại một artifact đã có sẵn."]],
  "rootCause": "<p>Ba nguyên nhân độc lập, mỗi cái sửa được riêng.</p><ul><li>Hai loại tệp bị áp một chính sách cache: tệp có hash không bao giờ đổi nội dung, còn <code>index.html</code> đổi mỗi lần deploy.</li><li>Bản deploy không phải một artifact bất biến, nên ghi đè tại chỗ làm bản cũ biến mất và lùi lại phải dựng lại từ mã nguồn.</li><li>Bucket mở công khai để CloudFront đọc được, nên bất kỳ ai biết tên bucket đều gọi thẳng S3 và bỏ qua mọi luật đặt ở biên.</li></ul>",
  "concept": "Tệp có hash trong tên không đổi nội dung nên cache lâu là đúng, còn index.html không có hash nên phải no-cache để mỗi lần mở trang đều hỏi lại; và mỗi bản build phải là một artifact bất biến để rollback chỉ là đổi con trỏ, không phải build lại.",
  "mechanism": "<p><strong>Ví von đời thường:</strong> <code>index.html</code> giống tấm bản đồ giấy phát ở cửa công viên — nó ghi tên các con đường; tệp JS có hash giống con đường đã đặt tên cố định, sửa đường thì đặt tên mới chứ không đổi tên cũ. Giới hạn: bản đồ giấy không tự cập nhật, còn <code>index.html</code> cập nhật được, nhưng chỉ khi trình duyệt chịu hỏi lại.</p><pre><code>index.html (không hash, phải no-cache)\n        │  trỏ tới\n        ▼\nassets/app.8083771c.js (có hash, cache 1 năm)\n        │\n        ▼\n   ┌──────────┐   có trong cache   ┌─────┐\n   │CloudFront│───────────────────→│ 200 │\n   └──────────┘                    └─────┘\n        │ không có, hỏi bucket\n        ▼\n   S3: tệp đã bị --delete xoá ──→ 404 ──→ trang trắng</code></pre><ol><li><strong>Bước 1 — Hash đến từ nội dung:</strong> nội dung đổi thì tên đổi, nên một tên đã phát hành không bao giờ mang nội dung khác, và tệp loại này cache được một năm.</li><li><strong>Bước 2 — index.html không có hash:</strong> nó là tệp duy nhất tên cố định mà nội dung đổi mỗi lần deploy, nên cache nó là cache một tấm bản đồ cũ.</li><li><strong>Bước 3 — no-cache không phải không lưu:</strong> nó nghĩa là trước khi dùng bản đã lưu, trình duyệt phải hỏi lại; chưa đổi thì nhận <code>304</code> và không tải lại byte nào.</li><li><strong>Bước 4 — Rollback cần artifact cũ còn nguyên:</strong> tệp của bản cũ phải còn trên bucket và bản build cũ phải được lưu kèm một con trỏ, nên rollback là ghi lại con trỏ chứ không phải build lại.</li></ol>",
  "visuals": [{"id": "flow-deploy-cache", "question": "Vì sao index.html phải no-cache trong khi tệp JS có hash lại cache một năm, và rollback đi qua những bước nào?", "focus": "index.html: no-cache"}],
  "failureModes": "<p>Bốn kiểu hỏng của chính cách deploy này.</p><ul><li><strong>index.html lại bị cache.</strong> Niềm tin sai: đã khai <code>no-cache</code> trong pipeline là xong. Nghe hợp lý vì header có thật trong lệnh <code>s3 cp</code>. Điều đúng: giá trị cache hiệu lực là giá trị đi kèm object tại thời điểm ghi, nên một lần đẩy tay hoặc một luật cache mặc định ở CloudFront là header trong pipeline bị ghi đè. Phản chứng: sau deploy, người dùng vẫn thấy bản cũ cho tới khi xoá cache trình duyệt.</li><li><strong>Asset cũ bị xoá bởi thao tác dọn.</strong> Niềm tin sai: giữ asset cũ là rác, dọn cho gọn. Nghe hợp lý vì bucket sạch thì dễ nhìn. Điều đúng: tab đang mở của người dùng vẫn cần tệp của bản cũ, nên chỉ được dọn sau khi không còn bản nào trỏ tới. Phản chứng: tỉ lệ 404 trên asset tăng trong vài giờ sau mỗi lần dọn, đúng ở nhóm người dùng mở tab lâu.</li><li><strong>Rollback không tái tạo đúng bản cũ.</strong> Niềm tin sai: revert commit rồi build lại là quay về đúng trạng thái trước. Nghe hợp lý vì mã nguồn thì không đổi. Điều đúng: registry và phiên bản thư viện ở thời điểm build đã khác, nên bản dựng ra không giống bản đã chạy. Phản chứng: sau rollback, lỗi cũ không tái hiện, hoặc một lỗi mới xuất hiện chỉ ở bản vừa dựng lại.</li><li><strong>Migration không tương thích ngược.</strong> Niềm tin sai: deploy code và chạy migration cùng lúc là một bước. Nghe hợp lý vì trong môi trường dev mọi thứ đổi cùng nhau. Điều đúng: trong lúc chuyển, bản cũ và bản mới cùng chạy, nên migration xoá cột mà bản cũ còn đọc là bản cũ chết ngay, và rollback cũng không cứu được. Phản chứng: lỗi 500 xuất hiện rải rác trong vài phút deploy rồi tự hết khi mọi instance đã lên bản mới.</li></ul>",
  "tradeoff": "<p><strong>Được gì:</strong> người dùng đang mở tab không còn nhận màn hình trắng, vì <code>index.html</code> luôn được hỏi lại và tệp có hash không bao giờ bị thay nội dung. Rollback trở thành thao tác vài giây thay vì một cuộc dựng lại có thể thất bại đúng lúc cần nhất.</p><p><strong>Mất gì:</strong> mỗi bản build để lại một bộ tệp phải giữ và một chính sách dọn phải viết đúng; hai chính sách cache là hai chỗ có thể cấu hình sai; thêm bước <code>cache invalidation</code> (vô hiệu hóa bộ nhớ đệm cũ trên CloudFront) sau mỗi lần promote.</p><p><strong>Rủi ro:</strong> sai ở <code>index.html</code> thì hậu quả nặng hơn sai ở asset; và bước dọn asset theo tuổi có thể xoá đúng thứ người dùng còn cần.</p><p><strong>Vì sao vẫn đáng:</strong> cái giá là vài dòng cấu hình, còn cái mất là người dùng thấy trang trắng ngay sau một lần deploy đúng.</p>",
  "alternatives": "<p><strong>Khi nào KHÔNG nên dùng:</strong> khi trang không có người dùng thật, hoặc khi chỉ có một bản duy nhất không bao giờ rollback.</p><ul><li><strong>Trang thử nghiệm nội bộ:</strong> thứ tự đẩy và hai chính sách cache không đáng bận tâm vì không ai giữ tab cũ.</li><li><strong>Nền tảng hosting tĩnh có CDN tích hợp:</strong> chọn khi đội không muốn tự quản bucket, OAC và invalidate; cái giá là ít quyền kiểm soát header và luật ở biên.</li><li><strong>Phục vụ index.html từ chính API:</strong> chọn khi cần render phía server để nhét cấu hình theo từng người dùng; cái giá là mỗi lần mở trang đều chạm backend.</li><li><strong>blue-green / rolling deploy</strong> (triển khai cuốn chiếu nơi bản cũ và bản mới cùng chạy song song): chỉ đáng khi có nhiều instance và cần chuyển lưu lượng dần; với một trang tĩnh một bản, nó chỉ thêm bước mà không đổi kết quả.</li></ul>",
  "observe": "<p>Bốn tín hiệu, mỗi tín hiệu theo dõi một quyết định.</p><ul><li><strong>Tỉ lệ 404 trên đường dẫn asset.</strong> Tăng ngay sau deploy nghĩa là có <code>index.html</code> cũ đang trỏ tới tệp đã bị xoá; đây là tín hiệu sớm nhất và cũng là tín hiệu duy nhất người dùng cảm nhận được trước khi họ báo.</li><li><strong>Tỉ lệ phản hồi 200 so với 304 cho <code>index.html</code>.</strong> Gần như toàn 200 nghĩa là mỗi lần mở trang đều tải lại toàn bộ tệp, tức là <code>no-cache</code> đã bị đổi thành <code>no-store</code>; gần như toàn 304 và không có 200 nào sau deploy nghĩa là header không được áp dụng.</li><li><strong>Phiên bản đang phục vụ ở biên so với artifact mong muốn.</strong> Trả một header chứa mã bản build rồi so sau mỗi lần promote; lệch nghĩa là invalidate chưa lan tới mọi điểm biên.</li><li><strong>Thời gian từ promote tới khi mọi điểm biên phục vụ bản mới.</strong> Đây là con số quyết định bạn dám rollback nhanh tới đâu, vì rollback cũng đi qua đúng con đường đó.</li></ul>",
  "attacks": [{"q":"Vite đã gắn mã hash vào tên mọi file JS và CSS rồi, vậy tại sao file index.html ở gốc bucket lại bắt buộc phải đặt Cache-Control: no-cache mà không được cache lâu?","a":"<p><strong>Trả lời mẫu (30–60 giây):</strong> Vì chính cái tên <code>index.html</code> không có hash. Nó là tấm bản đồ chứa đường dẫn tới các tệp có hash của từng bản. Nếu cache nó 24 giờ, người đã vào lúc 9 giờ vẫn dùng bản đồ cũ tới 9 giờ hôm sau; nếu tệp JS cũ đã bị xoá thì họ nhận <code>404</code> và màn hình trắng. <code>no-cache</code> không cấm lưu: nó bắt trình duyệt gửi <code>If-None-Match</code> để hỏi lại, chưa đổi thì nhận <code>304</code> và không tải lại byte nào.</p><p><strong>Lỗi hay mắc khi trả lời:</strong> nói \"<code>no-cache</code> là không được cache\" — cách nói đúng là <code>no-store</code> mới là không lưu, còn <code>no-cache</code> là phải hỏi lại trước khi dùng.</p>"},{"q":"Tại sao phải cấu hình CloudFront Origin Access Control (OAC) phức tạp mà không bật Public Read cho S3 Bucket chứa web và ảnh cho nhanh?","a":"<p><strong>Trả lời mẫu (30–60 giây):</strong> Vì public read cho phép cả thế giới đi đường vòng qua CloudFront. Mọi luật WAF, chặn theo vùng và giới hạn tốc độ đặt ở biên trở nên vô nghĩa khi kẻ tấn công gọi thẳng địa chỉ bucket, và họ tải lặp tệp lớn để đốt tiền băng thông chiều ra. Với OAC, bucket bật Block Public Access và chỉ nhận request có chữ ký từ đúng distribution, nên mọi request đều đi qua lớp bạn kiểm soát.</p><p><strong>Lỗi hay mắc khi trả lời:</strong> nói \"bucket public cũng được vì URL khó đoán\" — cách nói đúng là tên bucket lộ qua log, qua referrer và qua chính các tệp đã tải.</p>"},{"q":"Khi phát hiện bản vừa deploy lên Production bị lỗi, tại sao bạn không chạy git revert rồi cho GitHub Actions chạy lại npm run build từ đầu để rollback?","a":"<p><strong>Trả lời mẫu (30–60 giây):</strong> Vì hai lý do: thời gian và tính tất định. Khởi tạo CI, kéo code, cài phụ thuộc rồi build tốn vài phút, trong khi chép <code>index.html</code> của bản cũ ra gốc bucket mất vài giây vì asset cũ vẫn còn. Và bản dựng lại không phải bản đã chạy: nếu một thư viện vừa lên phiên bản mới, hash đổi và bạn vừa phát hành một artifact chưa ai chạy thử. Trong mô phỏng, hai đường dẫn trùng nhau bằng <code>False</code>.</p><p><strong>Lỗi hay mắc khi trả lời:</strong> nói \"cùng commit thì cùng bản build\" — cách nói đúng là bản build là hàm của mã nguồn và môi trường build.</p>"},{"q":"Sau mỗi lần deploy tôi chỉ cần chạy invalidate /* cho CloudFront là mọi người nhận bản mới, vậy tại sao còn phải chia hai chính sách cache làm gì cho phức tạp?","a":"<p><strong>Trả lời mẫu (30–60 giây):</strong> Vì invalidate không sửa được nguyên nhân và có ba cái giá. Một, nó không chạm tới trình duyệt: máy khách vẫn giữ <code>index.html</code> theo <code>max-age</code> đã khai. Hai, <code>/*</code> xoá luôn cache của tệp có hash — thứ đáng được giữ — nên đúng lúc deploy là lúc origin chịu tải cao nhất. Ba, invalidate tính tiền theo số đường dẫn và không lan truyền tức thời. Invalidate đúng một đường dẫn <code>/index.html</code> là đủ.</p><p><strong>Lỗi hay mắc khi trả lời:</strong> nói \"invalidate là cách thay cho cache policy\" — cách nói đúng là invalidate là biện pháp chữa cháy, còn chính sách cache là thứ quyết định ai giữ gì.</p>"}],
  "anchor": "Deploy là đổi con trỏ tới một artifact bất biến, không phải ghi đè tại chỗ.",
  "say30": "Tôi build Vue ra dist rồi đẩy tệp có hash lên bucket private với cache một năm và không xoá bản cũ; index.html đẩy sau cùng với no-cache. CloudFront đọc bucket qua OAC nên không ai gọi thẳng S3 được. Rollback là chép index.html của release cũ ra gốc rồi invalidate, mất vài giây, không build lại. Mỗi bản build là một artifact bất biến, và migration đi trước theo kiểu tương thích ngược.",
  "say90": "[Nêu vấn đề (30s)]: index.html là tệp duy nhất không có hash trong tên, nên nếu nó bị cache cùng chính sách với tệp JS thì trình duyệt dùng bản cũ và trỏ vào tệp mà bước --delete vừa xoá: người dùng thấy màn hình trắng, còn máy đội thì vẫn bình thường. Cùng lúc, build lại cũng không tái tạo đúng bản cũ, vì registry và phiên bản thư viện đã khác.\n\n[Cơ chế (45s)]: Hai chính sách cache cho hai loại tệp: tệp có hash không bao giờ đổi nội dung nên cache một năm và immutable, còn index.html để no-cache để mỗi lần mở trang đều hỏi lại và nhận 304 khi chưa đổi. Thứ tự đẩy quan trọng: asset trước, index sau cùng. Bucket để private, bật Block Public Access và cho CloudFront ký yêu cầu bằng OAC, nên mọi request đều đi qua CloudFront. Migration đi trước theo kiểu tương thích ngược để bản cũ và bản mới cùng chạy.\n\n[Ranh giới (15s)]: Không cứu được tab đang chạy JS cũ gọi vào API đã đổi, và nó bắt bạn giữ artifact cũ cùng một chính sách dọn đúng; đổi lại rollback là vài giây thay vì bốn mươi phút.",
  "body": "<p><strong>Ví dụ chuyển giao.</strong> Phát hành bản 2.4 với ba thay đổi trong một lần deploy. Migration đổi tên cột <code>phone</code> thành <code>contact_phone</code> trong khi container cũ vẫn truy vấn <code>phone</code>, nên lỗi <code>500</code> hàng loạt.</p><p>Cùng lúc, lệnh sync kèm <code>--delete</code> với cache 24 giờ cho mọi tệp khiến <code>index.html</code> cũ trỏ tới JS đã xoá, và bucket public cho phép đọc tệp trực tiếp.</p><p>Cách áp dụng: khoá public access và gắn OAC cho CloudFront. Tách deploy thành hai bước — asset có hash trước, <code>index.html</code> <code>no-cache</code> sau cùng. Migration đi theo expand rồi contract: thêm cột mới, code đọc cả hai, xoá cột cũ ở chu kỳ sau.</p><p>Ba dấu hiệu để nhận ra mình đang ở tình huống nào. Tỉ lệ <code>404</code> trên <code>/assets/</code> tăng ngay sau deploy: index cache lâu trỏ tới tệp đã xoá. Một URL S3 trực tiếp trả nội dung: bucket đang public. Rollback phải sửa tay trên production: không có artifact đánh số.</p>",
  "code": "# ✅ Cách làm chuẩn: artifact bất biến, đẩy theo thứ tự, rollback bằng cách trỏ lại artifact cũ.\n# .github/workflows/deploy.yml (rút gọn)\njobs:\n  deploy:\n    runs-on: ubuntu-latest\n    env:\n      BUCKET: app-bucket\n      DIST_ID: E1EXAMPLE\n    permissions:\n      id-token: write          # OIDC: không lưu access key dài hạn trong GitHub\n      contents: read\n    steps:\n      - uses: actions/checkout@v4\n      - name: Build Vue\n        run: npm ci && npm run build          # ra thư mục dist\n      - name: Gắn version theo commit\n        run: echo \"VERSION=${GITHUB_SHA::12}\" >> \"$GITHUB_ENV\"\n      - uses: aws-actions/configure-aws-credentials@v4\n        with:\n          role-to-assume: ${{ secrets.DEPLOY_ROLE_ARN }}   # role chỉ có quyền deploy\n          aws-region: ap-southeast-1\n      # 1. Assets có hash: chỉ ghi thêm, không xoá. Bản cũ còn cần cho người đang cầm HTML cũ.\n      - name: Upload assets\n        run: aws s3 sync dist/assets s3://$BUCKET/assets --cache-control \"public,max-age=31536000,immutable\"\n      # 2. Lưu index.html của bản này thành artifact đã đánh số.\n      - name: Archive artifact\n        run: aws s3 cp dist/index.html s3://$BUCKET/releases/$VERSION/index.html --cache-control no-cache\n      # 3. Smoke test trên staging trước khi đổi con trỏ.\n      - name: Smoke test\n        run: curl -fsS \"$STAGING_URL/health\" && curl -fsS \"$STAGING_URL/\" | grep -q 'id=\"app\"'\n      # 4. Promote: đổi con trỏ index.html ở gốc bucket. Rollback = chạy lại bước này với VERSION cũ.\n      - name: Promote\n        run: |\n          aws s3 cp s3://$BUCKET/releases/$VERSION/index.html s3://$BUCKET/index.html --cache-control no-cache --content-type \"text/html; charset=utf-8\"\n          aws cloudfront create-invalidation --distribution-id $DIST_ID --paths \"/index.html\"\n\n# ❌ Sai phổ biến: aws s3 sync dist s3://$BUCKET --delete\n# Lệnh này ghi đè index.html trước khi assets mới kịp lên, xoá JS mà HTML đã cache vẫn trỏ tới,\n# và không để lại bản ghi nào để rollback.",
  "codeNote": "<p><strong>Cách tệ so với cách tốt, nhìn từ khối code trên.</strong></p><ul><li><strong>Cách tệ:</strong> <code>aws s3 sync dist s3://$BUCKET --delete</code> — ghi đè <code>index.html</code> trước khi asset mới kịp lên, xoá JS mà HTML đã cache vẫn trỏ tới, và không để lại bản ghi nào để rollback.</li><li><strong>Cách tốt:</strong> đẩy <code>dist/assets</code> với <code>max-age=31536000, immutable</code> và không có <code>--delete</code>, nên tệp của bản cũ vẫn còn cho người đang mở tab cũ.</li><li>Lưu <code>releases/$VERSION/index.html</code> là bước biến bản deploy thành artifact có số, và là thứ khiến rollback không cần build.</li><li>Promote bằng cách chép index ra gốc với <code>no-cache</code> rồi invalidate đúng một đường dẫn, thay vì xoá cả cache bằng <code>/*</code>.</li><li><code>id-token: write</code> cùng <code>role-to-assume</code> để CI lấy quyền tạm thời, không lưu access key dài hạn trong repo.</li></ul>",
  "sayIt": ["Tôi build Vue ra dist, đẩy file có hash lên S3 private với cache một năm, rồi đẩy index.html cuối cùng với no-cache, và CloudFront đọc bucket qua OAC.","Migration đi trước theo kiểu tương thích ngược: thêm cột mới, để code đọc được cả hai dạng, rồi mới xoá cột cũ ở chu kỳ sau, vì trong lúc deploy bản cũ và bản mới cùng chạy.","Chỗ hỏng một là index.html cache lâu trỏ tới JS đã xoá, dấu hiệu là tỉ lệ 404 trên assets tăng ngay sau deploy; cách sửa là no-cache cho index.html và không xoá artifact cũ.","Chỗ hỏng hai là bucket public, dấu hiệu là một URL S3 trực tiếp trả nội dung; cách sửa là OAC và chặn public access ở cấp tài khoản.","Chỗ hỏng ba là rollback không có gì để trỏ về, dấu hiệu là phải sửa tay trên production; cách sửa là artifact đánh số theo commit SHA và rollback bằng cách đổi con trỏ.","Cả ba đều là hệ quả của việc deploy ghi đè tại chỗ, nên tôi giữ mỗi bản là một artifact bất biến và chuyển con trỏ có kiểm chứng bằng smoke test."],
  "qids": ["H07","H08","H13","G15"],
  "refs": ["aws-cloudfront","aws-cloudfront-oac","aws-s3-bpa","pg-transactions"],
}
);
